155:     // clouds
156:     ctx.fillStyle = 'rgba(220,230,225,.09)';
157:     [[0.16, 0.18, 70], [0.38, 0.1, 48], [0.62, 0.22, 62], [0.9, 0.14, 40]].forEach(([px, py, s]) => {
158:       const cx = px * this.w, cy = py * v.groundY;
159:       ctx.beginPath();
160:       ctx.ellipse(cx, cy, s, s * 0.22, 0, 0, TAU);
161:       ctx.ellipse(cx + s * 0.5, cy - s * 0.08, s * 0.5, s * 0.18, 0, 0, TAU);
162:       ctx.fill();
163:     });
164: 
165:     // horizon haze
166:     const haze = ctx.createLinearGradient(0, v.groundY - 40, 0, v.groundY);
167:     haze.addColorStop(0, 'rgba(255,190,130,0)');
168:     haze.addColorStop(1, 'rgba(255,190,130,.12)');
169:     ctx.fillStyle = haze;
170:     ctx.fillRect(0, v.groundY - 40, this.w, 40);
171:   }
172: 
173:   drawGroundLayers(ctx, v, game) {
174:     const c = game.contract;
175:     const bottom = this.h + 20;
176:     ctx.save();
177:     ctx.beginPath();
178:     ctx.rect(0, v.groundY, this.w, this.h - v.groundY);
179:     ctx.clip();
180: 
181:     ctx.fillStyle = '#241d17';
182:     ctx.fillRect(0, v.groundY, this.w, bottom - v.groundY);
183: 
184:     for (const layer of c.layers) {
185:       const y0 = this.Y(layer.top);
186:       const y1 = this.Y(layer.bottom);
187:       if (y1 < v.groundY - 10) continue;
188:       const grad = ctx.createLinearGradient(0, y0, 0, y1);
189:       grad.addColorStop(0, layer.color);
190:       grad.addColorStop(1, this.shade(layer.color, -12));
191:       ctx.fillStyle = grad;
192:       ctx.beginPath();
193:       ctx.moveTo(0, y0);
194:       for (let x = 0; x <= this.w + 30; x += 30) {
195:         const wx = v.x0 + x / v.sx;
196:         ctx.lineTo(x, y0 + Math.sin(wx * 0.13 + layer.top * 3) * Math.min(2.5, v.sy * 0.07));
197:       }
198:       ctx.lineTo(this.w, y1 + 30);
199:       ctx.lineTo(0, y1 + 30);
200:       ctx.closePath();
201:       ctx.fill();
202:       // boundary line
203:       ctx.strokeStyle = 'rgba(255,225,190,.075)';
204:       ctx.lineWidth = 1;
205:       ctx.beginPath();
206:       for (let x = 0; x <= this.w + 30; x += 30) {
207:         const wx = v.x0 + x / v.sx;
208:         const y = y0 + Math.sin(wx * 0.13 + layer.top * 3) * Math.min(2.5, v.sy * 0.07);
209:         x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
210:       }
211:       ctx.stroke();
212:     }
213: 
214:     if (this.texture) {
215:       for (const p of this.texture.dots) {
216:         const x = this.X(p.x), y = this.Y(p.d);
217:         if (x < -10 || x > this.w + 10 || y < v.groundY || y > this.h + 10) continue;
218:         ctx.fillStyle = p.light ? `rgba(255,230,195,${p.a})` : `rgba(20,12,8,${p.a * 1.4})`;
219:         ctx.beginPath();
220:         ctx.ellipse(x, y, p.r, p.r * 0.62, p.r, 0, TAU);
221:         ctx.fill();
222:       }
223:     }
224: 
225:     // grass strip
226:     ctx.fillStyle = '#3b4a2f';
227:     ctx.fillRect(0, v.groundY - 3, this.w, 4);
228:     ctx.fillStyle = 'rgba(146,164,102,.5)';
229:     ctx.fillRect(0, v.groundY - 3, this.w, 1.5);
230:     if (this.texture) {
231:       ctx.strokeStyle = 'rgba(118,140,82,.5)';
232:       ctx.lineWidth = 1;
233:       for (const g of this.texture.grass) {
234:         const x = this.X(g.x);
235:         if (x < -4 || x > this.w + 4) continue;
236:         ctx.beginPath();
237:         ctx.moveTo(x, v.groundY - 2);
238:         ctx.lineTo(x + g.lean, v.groundY - 2 - g.h);
239:         ctx.stroke();
240:       }
241:     }
242:     ctx.restore();
243:   }
244: 
245:   shade(hex, amt) {
246:     const n = parseInt(hex.slice(1), 16);
247:     const r = clamp((n >> 16) + amt, 0, 255);
248:     const g = clamp(((n >> 8) & 255) + amt, 0, 255);
249:     const b = clamp((n & 255) + amt, 0, 255);
250:     return `rgb(${r},${g},${b})`;
251:   }
