253:   drawGrid(ctx, v, game) {
254:     const c = game.contract;
255:     ctx.save();
256:     ctx.lineWidth = 1;
257:     ctx.font = '9px "JetBrains Mono", monospace';
258:     ctx.textAlign = 'left';
259:     const step = v.narrow ? 20 : 20;
260:     const first = Math.ceil(v.x0 / step) * step;
261:     for (let x = first; x <= v.x1; x += step) {
262:       const sx = this.X(x);
263:       ctx.strokeStyle = 'rgba(160,195,215,.055)';
264:       ctx.beginPath(); ctx.moveTo(sx, v.groundY); ctx.lineTo(sx, this.h); ctx.stroke();
265:       ctx.fillStyle = 'rgba(182,208,220,.38)';
266:       ctx.fillText(`${x} м`, sx + 4, v.groundY + 12);
267:     }
268:     const dStep = 2;
269:     for (let d = 2; d <= v.depth; d += dStep) {
270:       const sy = this.Y(d);
271:       if (sy > this.h - 4) break;
272:       ctx.strokeStyle = 'rgba(160,195,215,.045)';
273:       ctx.beginPath(); ctx.moveTo(0, sy); ctx.lineTo(this.w, sy); ctx.stroke();
274:       ctx.fillStyle = 'rgba(182,208,220,.32)';
275:       ctx.fillText(`−${d}`, 6, sy - 4);
276:     }
277:     ctx.restore();
278:   }
