400:   drawBore(ctx, v, game, t) {
401:     const path = game.path;
402:     if (!path || path.length < 2) return;
403:     const screen = path.map(p => ({ x: this.X(p.x), y: this.Y(p.d), d: p.d, wx: p.x }));
404:     ctx.save();
405:     ctx.lineJoin = 'round';
406:     ctx.lineCap = 'round';
407:     // outer
408:     ctx.strokeStyle = 'rgba(5,8,10,.92)';
409:     ctx.lineWidth = Math.max(9, v.sy * 0.35);
410:     ctx.beginPath();
411:     screen.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
412:     ctx.stroke();
413:     // inner shadow
414:     ctx.strokeStyle = '#2a1e15';
415:     ctx.lineWidth = Math.max(6, v.sy * 0.24);
416:     ctx.stroke();
417:     // bore glow
418:     ctx.shadowColor = 'rgba(255,122,26,.5)';
419:     ctx.shadowBlur = 9;
420:     ctx.strokeStyle = '#ff7a1a';
421:     ctx.lineWidth = 2.6;
422:     ctx.stroke();
423:     ctx.shadowBlur = 0;
424: 
425:     // rod joints
426:     const jointEvery = 3;
427:     let acc = 0;
428:     for (let i = 1; i < path.length; i++) {
429:       const a = path[i - 1], b = path[i];
430:       const len = Math.hypot(b.x - a.x, b.d - a.d);
431:       acc += len;
432:       if (acc >= jointEvery) {
433:         acc = 0;
434:         const x = this.X(b.x), y = this.Y(b.d);
435:         const dx = this.X(b.x) - this.X(a.x), dy = this.Y(b.d) - this.Y(a.d);
436:         const ang = Math.atan2(dy, dx) + Math.PI / 2;
437:         ctx.strokeStyle = 'rgba(255,200,140,.5)';
438:         ctx.lineWidth = 1;
439:         ctx.beginPath();
440:         ctx.moveTo(x - Math.cos(ang) * 3, y - Math.sin(ang) * 3);
441:         ctx.lineTo(x + Math.cos(ang) * 3, y + Math.sin(ang) * 3);
442:         ctx.stroke();
443:       }
444:     }
445: 
446:     // moving mud specks inside bore
447:     if (game.stage === 'pilot' || game.stage === 'mud' || game.stage === 'ream' || game.stage === 'pull') {
448:       const n = Math.min(40, Math.max(8, Math.floor(path.length / 2)));
449:       for (let i = 0; i < n; i++) {
450:         const idx = (i * 3 + Math.floor(t * 5)) % path.length;
451:         const p = screen[idx];
452:         ctx.fillStyle = `rgba(255,210,150,${0.18 + 0.12 * Math.sin(t * 4 + i)})`;
453:         ctx.beginPath(); ctx.arc(p.x, p.y, 1.4, 0, TAU); ctx.fill();
454:       }
455:     }
456: 
457:     // sonde pulses
458:     if (game.stage === 'pilot' && game.head) {
459:       const hx = this.X(game.head.x), hy = this.Y(game.head.d);
460:       for (let i = 0; i < 3; i++) {
461:         const ph = (t * 0.7 + i / 3) % 1;
462:         ctx.strokeStyle = `rgba(94,214,255,${(1 - ph) * 0.25})`;
463:         ctx.lineWidth = 1.2;
464:         ctx.beginPath(); ctx.arc(hx, hy, 8 + ph * 30, 0, TAU); ctx.stroke();
465:       }
466:     }
467:     ctx.restore();
468:   }
