610:   drawTrailer(ctx, x, gy, s) {
611:     ctx.save();
612:     ctx.fillStyle = '#c9d2d3';
613:     this.rr(ctx, x - 34 * s, gy - 44 * s, 68 * s, 40 * s, 3 * s); ctx.fill();
