export function buildLayers(soil) {
  const p = LAYER_PALETTES[soil] || LAYER_PALETTES.loam;
  return p.tops.slice(0, -1).map((top, i) => ({
    name: p.names[i], top, bottom: p.tops[i + 1], color: p.colors[i], hardness: p.hardness[i]
  }));
}

