      mechanic: { x: this.X(v.narrow ? -6.6 : -7.1) },
      foreman: { x: this.X(8.5) }
    };
    if (game.stage === 'pilot' && game.head) {
      positions.locator.x = this.X(Math.min(c.length, game.head.x + 1.6));
