    const wobble = Math.sin(this.simT * 1.4) * 2.8 + Math.sin(this.simT * 3.7 + 1) * 1.4;
    const target = this.reamBase + (pulling ? 20 : 0) - (sd.mud ? 14 : 0) + (sd.progress / 100) * 8 + wobble;
    sd.load = lerp(sd.load, target, 1 - Math.exp(-dt * 3.1));
