428:     this.fx.frac = Math.max(0, this.fx.frac - dt);
429:     this.fx.shake = Math.max(0, this.fx.shake - dt * 2.2);
430:     if (this.drillPause > 0) {
431:       this.drillPause -= dt;
432:       this.updateHud();
433:       return;
434:     }
435:     switch (this.stage) {
436:       case 'pilot': this.updatePilot(dt); break;
437:       case 'mud': this.updateMud(dt); break;
438:       case 'ream': this.updateReam(dt); break;
439:       case 'pull': this.updatePull(dt); break;
440:     }
441:     this.updateHud();
