45:       this.canvas.width = Math.round(r.width * dpr);
46:       this.canvas.height = Math.round(r.height * dpr);
47:     }
48:     return true;
49:   }
50: 
51:   view(game) {
52:     const c = game.contract;
53:     const narrow = this.w < 620;
54:     const full = this.demo || game.stage === 'prep' || game.stage === 'mud' || game.stage === 'results';
55:     let x0, x1;
56:     if (full) {
57:       x0 = narrow ? -13 : -24;
58:       x1 = c.length + (narrow ? 13 : 21);
59:     } else {
60:       let focus = game.head ? game.head.x : 0;
61:       if (game.stage === 'ream' || game.stage === 'pull') {
62:         const p = game.stageData?.progress || 0;
63:         focus = c.length * (1 - p / 100);
64:       }
65:       const vw = narrow ? 33 : 58;
66:       const maxX0 = Math.max(-24, c.length + 13 - vw);
67:       x0 = clamp(focus - vw * 0.42, -24, maxX0);
68:       x1 = x0 + vw;
69:     }
70:     const groundY = this.h * (full ? (narrow ? 0.285 : 0.305) : 0.325);
71:     const depth = full ? c.maxDepth + 3.4 : (narrow ? 10 : 9.4);
72:     const sy = (this.h - groundY - 14) / depth;
73:     const sx = this.w / (x1 - x0);
74:     return { x0, x1, groundY, sx, sy, full, narrow, depth };
75:   }
76: 
77:   draw(game, time) {
78:     if (!this.resize()) return;
79:     const ctx = this.ctx;
80:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
81:     ctx.clearRect(0, 0, this.w, this.h);
82:     const view = this.view(game);
83:     this.v = view;
84:     this.setContract(game.contract);
85: 
86:     const shake = game.fx?.shake || 0;
87:     ctx.save();
88:     if (shake > 0.1) {
89:       ctx.translate((Math.random() - 0.5) * shake * 9, (Math.random() - 0.5) * shake * 7);
90:     }
91: 
92:     this.drawSky(ctx, view, time, game);
93:     this.drawGroundLayers(ctx, view, game);
94:     this.drawGrid(ctx, view, game);
95:     this.drawPits(ctx, view, game);
96:     this.drawUtilities(ctx, view, game, time);
97:     this.drawDesign(ctx, view, game);
98:     this.drawBore(ctx, view, game, time);
99:     this.drawEquipment(ctx, view, game, time);
100:     this.drawTools(ctx, view, game, time);
101:     this.drawCrew(ctx, view, game, time);
102:     this.drawFx(ctx, view, game, time);
103:     this.drawUtilityLabels(ctx, view, game);
104:     ctx.restore();
105:   }
106: 
107:   X(x) { return (x - this.v.x0) * this.v.sx; }
108:   Y(d) { return this.v.groundY + d * this.v.sy; }
109: 
110:   rr(ctx, x, y, w, h, r) {
111:     const k = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
112:     ctx.beginPath();
113:     ctx.moveTo(x + k, y);
114:     ctx.arcTo(x + w, y, x + w, y + h, k);
115:     ctx.arcTo(x + w, y + h, x, y + h, k);
116:     ctx.arcTo(x, y + h, x, y, k);
117:     ctx.arcTo(x, y, x + w, y, k);
118:     ctx.closePath();
119:   }
120: 
121:   drawSky(ctx, v, t, game) {
122:     const g = ctx.createLinearGradient(0, 0, 0, v.groundY);
123:     g.addColorStop(0, '#08151f');
124:     g.addColorStop(0.4, '#173444');
125:     g.addColorStop(0.72, '#3f5c63');
126:     g.addColorStop(0.92, '#a47a52');
127:     g.addColorStop(1, '#c3945f');
128:     ctx.fillStyle = g;
129:     ctx.fillRect(0, 0, this.w, v.groundY + 2);
130: 
131:     const sunX = this.w * 0.79, sunY = v.groundY * 0.35;
132:     const sun = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, this.w * 0.22);
133:     sun.addColorStop(0, 'rgba(255,214,160,.55)');
134:     sun.addColorStop(0.35, 'rgba(255,180,110,.14)');
135:     sun.addColorStop(1, 'rgba(255,170,100,0)');
136:     ctx.fillStyle = sun;
137:     ctx.fillRect(0, 0, this.w, v.groundY);
138: 
139:     ctx.fillStyle = 'rgba(255,236,205,.55)';
140:     ctx.beginPath(); ctx.arc(sunX, sunY, Math.max(12, this.w * 0.018), 0, TAU); ctx.fill();
141: 
142:     // distant hills
143:     const hill = (base, amp, freq, color) => {
144:       ctx.beginPath();
145:       ctx.moveTo(0, v.groundY);
146:       for (let x = 0; x <= this.w + 20; x += 24) {
147:         ctx.lineTo(x, base - Math.sin(x * freq + 1.4) * amp - Math.sin(x * freq * 2.3) * amp * 0.3);
148:       }
149:       ctx.lineTo(this.w, v.groundY); ctx.closePath();
150:       ctx.fillStyle = color; ctx.fill();
151:     };
152:     hill(v.groundY - 2, 9, 0.007, '#193642');
153:     hill(v.groundY + 1, 5, 0.012, '#1c3b3e');
154: 
155:     // clouds
156:     ctx.fillStyle = 'rgba(220,230,225,.09)';
157:     [[0.16, 0.18, 70], [0.38, 0.1, 48], [0.62, 0.22, 62], [0.9, 0.14, 40]].forEach(([px, py, s]) => {
158:       const cx = px * this.w, cy = py * v.groundY;
159:       ctx.beginPath();
160:       ctx.ellipse(cx, cy, s, s * 0.22, 0, 0, TAU);
161:       ctx.ellipse(cx + s * 0.5, cy - s * 0.08, s * 0.5, s * 0.18, 0, 0, TAU);
162:       ctx.fill();
163:     });
164: 
165:     // horizon haze
166:     const haze = ctx.createLinearGradient(0, v.groundY - 40, 0, v.groundY);
167:     haze.addColorStop(0, 'rgba(255,190,130,0)');
168:     haze.addColorStop(1, 'rgba(255,190,130,.12)');
169:     ctx.fillStyle = haze;
170:     ctx.fillRect(0, v.groundY - 40, this.w, 40);
171:   }
172: 
173:   drawGroundLayers(ctx, v, game) {
174:     const c = game.contract;
175:     const bottom = this.h + 20;
176:     ctx.save();
177:     ctx.beginPath();
178:     ctx.rect(0, v.groundY, this.w, this.h - v.groundY);
179:     ctx.clip();
180: 
181:     ctx.fillStyle = '#241d17';
182:     ctx.fillRect(0, v.groundY, this.w, bottom - v.groundY);
183: 
184:     for (const layer of c.layers) {
185:       const y0 = this.Y(layer.top);
186:       const y1 = this.Y(layer.bottom);
187:       if (y1 < v.groundY - 10) continue;
188:       const grad = ctx.createLinearGradient(0, y0, 0, y1);
189:       grad.addColorStop(0, layer.color);
190:       grad.addColorStop(1, this.shade(layer.color, -12));
191:       ctx.fillStyle = grad;
192:       ctx.beginPath();
193:       ctx.moveTo(0, y0);
194:       for (let x = 0; x <= this.w + 30; x += 30) {
195:         const wx = v.x0 + x / v.sx;
196:         ctx.lineTo(x, y0 + Math.sin(wx * 0.13 + layer.top * 3) * Math.min(2.5, v.sy * 0.07));
197:       }
198:       ctx.lineTo(this.w, y1 + 30);
199:       ctx.lineTo(0, y1 + 30);
200:       ctx.closePath();
201:       ctx.fill();
202:       // boundary line
203:       ctx.strokeStyle = 'rgba(255,225,190,.075)';
204:       ctx.lineWidth = 1;
205:       ctx.beginPath();
206:       for (let x = 0; x <= this.w + 30; x += 30) {
207:         const wx = v.x0 + x / v.sx;
208:         const y = y0 + Math.sin(wx * 0.13 + layer.top * 3) * Math.min(2.5, v.sy * 0.07);
209:         x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
210:       }
211:       ctx.stroke();
212:     }
213: 
214:     if (this.texture) {
215:       for (const p of this.texture.dots) {
216:         const x = this.X(p.x), y = this.Y(p.d);
217:         if (x < -10 || x > this.w + 10 || y < v.groundY || y > this.h + 10) continue;
218:         ctx.fillStyle = p.light ? `rgba(255,230,195,${p.a})` : `rgba(20,12,8,${p.a * 1.4})`;
219:         ctx.beginPath();
220:         ctx.ellipse(x, y, p.r, p.r * 0.62, p.r, 0, TAU);
221:         ctx.fill();
222:       }
223:     }
224: 
225:     // grass strip
226:     ctx.fillStyle = '#3b4a2f';
227:     ctx.fillRect(0, v.groundY - 3, this.w, 4);
228:     ctx.fillStyle = 'rgba(146,164,102,.5)';
229:     ctx.fillRect(0, v.groundY - 3, this.w, 1.5);
230:     if (this.texture) {
231:       ctx.strokeStyle = 'rgba(118,140,82,.5)';
232:       ctx.lineWidth = 1;
233:       for (const g of this.texture.grass) {
234:         const x = this.X(g.x);
235:         if (x < -4 || x > this.w + 4) continue;
236:         ctx.beginPath();
237:         ctx.moveTo(x, v.groundY - 2);
238:         ctx.lineTo(x + g.lean, v.groundY - 2 - g.h);
239:         ctx.stroke();
240:       }
241:     }
242:     ctx.restore();
243:   }
244: 
245:   shade(hex, amt) {
246:     const n = parseInt(hex.slice(1), 16);
247:     const r = clamp((n >> 16) + amt, 0, 255);
248:     const g = clamp(((n >> 8) & 255) + amt, 0, 255);
249:     const b = clamp((n & 255) + amt, 0, 255);
250:     return `rgb(${r},${g},${b})`;
251:   }
252: 
253:   drawGrid(ctx, v, game) {
254:     const c = game.contract;
255:     ctx.save();
256:     ctx.lineWidth = 1;
257:     ctx.font = '9px "JetBrains Mono", monospace';
258:     ctx.textAlign = 'left';
259:     const step = v.narrow ? 20 : 20;
260:     const first = Math.ceil(v.x0 / step) * step;
261:     for (let x = first; x <= v.x1; x += step) {
262:       const sx = this.X(x);
263:       ctx.strokeStyle = 'rgba(160,195,215,.055)';
264:       ctx.beginPath(); ctx.moveTo(sx, v.groundY); ctx.lineTo(sx, this.h); ctx.stroke();
265:       ctx.fillStyle = 'rgba(182,208,220,.38)';
266:       ctx.fillText(`${x} м`, sx + 4, v.groundY + 12);
267:     }
268:     const dStep = 2;
269:     for (let d = 2; d <= v.depth; d += dStep) {
270:       const sy = this.Y(d);
271:       if (sy > this.h - 4) break;
272:       ctx.strokeStyle = 'rgba(160,195,215,.045)';
273:       ctx.beginPath(); ctx.moveTo(0, sy); ctx.lineTo(this.w, sy); ctx.stroke();
274:       ctx.fillStyle = 'rgba(182,208,220,.32)';
275:       ctx.fillText(`−${d}`, 6, sy - 4);
276:     }
277:     ctx.restore();
278:   }
279: 
280:   drawUtilities(ctx, v, game, t) {
281:     const utils = game.utilities || [];
282:     for (const u of utils) {
283:       const x = this.X(u.x);
284:       if (x < -60 || x > this.w + 60) continue;
285:       const y = this.Y(u.depth);
286:       if (y > this.h + 20) continue;
287:       const known = u.revealed !== false;
288:       if (!known && !u.detected) continue;
289:       const col = u.color || UTILITY_TYPES[u.type]?.color || '#5ed6ff';
290:       const r = Math.max(5.5, (u.size || 0.15) * v.sy * 0.9);
291:       const hz = Math.max(13, u.clearance * v.sx);
292:       const pulse = 0.5 + Math.sin(t * 3 + u.x) * 0.5;
293: 
294:       // hazard column
295:       ctx.save();
296:       const band = ctx.createLinearGradient(0, v.groundY, 0, y + r * 2);
297:       band.addColorStop(0, known ? 'rgba(255,120,90,.02)' : 'rgba(255,90,90,.02)');
298:       band.addColorStop(1, known ? 'rgba(255,120,90,.12)' : 'rgba(255,90,90,.16)');
299:       ctx.fillStyle = band;
300:       ctx.fillRect(x - hz, v.groundY, hz * 2, Math.max(8, y + r * 2 - v.groundY));
301:       ctx.strokeStyle = known ? `rgba(255,170,120,${0.16 + pulse * 0.1})` : `rgba(255,90,90,${0.25 + pulse * 0.2})`;
302:       ctx.setLineDash([3, 5]);
303:       ctx.lineWidth = 1;
304:       ctx.beginPath(); ctx.moveTo(x, v.groundY); ctx.lineTo(x, y + r * 2.2); ctx.stroke();
305:       ctx.setLineDash([]);
306: 
307:       // clearance ring
308:       ctx.strokeStyle = known ? 'rgba(255,150,110,.28)' : 'rgba(255,90,90,.4)';
309:       ctx.setLineDash([4, 4]);
310:       ctx.beginPath();
311:       ctx.ellipse(x, y, Math.max(r * 2.1, hz * 0.9), Math.max(r * 2.1, (u.clearance || 0.6) * v.sy), 0, 0, TAU);
312:       ctx.stroke();
313:       ctx.setLineDash([]);
314: 
315:       // pipe / cable
316:       ctx.fillStyle = 'rgba(8,12,14,.9)';
317:       ctx.beginPath(); ctx.arc(x, y, r + 3, 0, TAU); ctx.fill();
318:       const pg = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, 1, x, y, r + 1);
319:       pg.addColorStop(0, this.lighten(col, 40));
320:       pg.addColorStop(1, col);
321:       ctx.fillStyle = pg;
322:       ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
323:       ctx.strokeStyle = 'rgba(0,0,0,.55)';
324:       ctx.lineWidth = 1.5;
325:       ctx.beginPath(); ctx.arc(x, y, r * 0.55, 0, TAU); ctx.stroke();
326: 
327:       if (!known) {
328:         ctx.fillStyle = 'rgba(255,120,100,.95)';
329:         ctx.font = 'bold 12px system-ui';
330:         ctx.textAlign = 'center';
331:         ctx.fillText('?', x, y - r - 8);
332:       } else {
333:         // surface marker
334:         ctx.fillStyle = col;
335:         ctx.beginPath();
336:         ctx.moveTo(x, v.groundY - 12);
337:         ctx.lineTo(x + 4, v.groundY - 5);
338:         ctx.lineTo(x - 4, v.groundY - 5);
339:         ctx.closePath();
340:         ctx.fill();
341:         ctx.fillStyle = 'rgba(7,16,23,.85)';
342:         ctx.beginPath(); ctx.arc(x, v.groundY - 4, 3.4, 0, TAU); ctx.fill();
343:       }
344:       ctx.restore();
345:     }
346: 
347:     // active sonde proximity warn
348:     if (game.stage === 'pilot' && game.head) {
349:       for (const u of utils) {
350:         if (u.revealed === false) continue;
351:         if (u.hit) continue;
352:         const dx = u.x - game.head.x;
353:         if (dx > -2 && dx < 14) {
354:           const x = this.X(u.x), y = this.Y(u.depth);
355:           ctx.strokeStyle = `rgba(255,100,90,${0.18 + (0.5 + Math.sin(t * 3) * 0.5) * 0.16})`;
356:           ctx.lineWidth = 2;
357:           ctx.setLineDash([3, 6]);
358:           ctx.beginPath(); ctx.arc(x, y, Math.max(16, u.clearance * v.sy), 0, TAU); ctx.stroke();
359:           ctx.setLineDash([]);
360:         }
361:       }
362:     }
363:   }
364: 
365:   lighten(hex, amt) {
366:     if (!hex || hex[0] !== '#') return hex;
367:     return this.shade(hex, amt);
368:   }
369: 
370:   drawDesign(ctx, v, game) {
371:     const c = game.contract;
372:     if (game.stage !== 'prep' && game.prep?.route === 'skip') return;
373:     const pts = game.design || c.design;
374:     ctx.save();
375:     ctx.strokeStyle = 'rgba(94,214,255,.72)';
376:     ctx.lineWidth = 1.6;
377:     ctx.setLineDash([8, 7]);
378:     ctx.beginPath();
379:     pts.forEach((p, i) => {
380:       const x = this.X(p.x), y = this.Y(p.d);
381:       i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
382:     });
383:     ctx.stroke();
384:     ctx.setLineDash([]);
385:     // direction arrows
386:     ctx.fillStyle = 'rgba(94,214,255,.8)';
387:     for (let i = 14; i < pts.length; i += 22) {
388:       const p = pts[i];
389:       const n = pts[Math.min(pts.length - 1, i + 2)];
390:       const x = this.X(p.x), y = this.Y(p.d);
391:       const ang = Math.atan2(this.Y(n.d) - y, this.X(n.x) - x);
392:       ctx.save();
393:       ctx.translate(x, y); ctx.rotate(ang);
394:       ctx.beginPath(); ctx.moveTo(4, 0); ctx.lineTo(-3, -3); ctx.lineTo(-3, 3); ctx.closePath(); ctx.fill();
395:       ctx.restore();
396:     }
397:     ctx.restore();
398:   }
399: 
400:   drawBore(ctx, v, game, t) {
401:     const path = game.path;
402:     if (!path || path.length < 2) return;
403:     const screen = path.map(p => ({ x: this.X(p.x), y: this.Y(p.d), d: p.d, wx: p.x }));
404:     ctx.save();
405:     ctx.lineJoin = 'round';
406:     ctx.lineCap = 'round';
407:     // outer
408:     ctx.strokeStyle = 'rgba(5,8,10,.92)';
409:     ctx.lineWidth = Math.max(9, v.sy * 0.35);
410:     ctx.beginPath();
411:     screen.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
412:     ctx.stroke();
413:     // inner shadow
414:     ctx.strokeStyle = '#2a1e15';
415:     ctx.lineWidth = Math.max(6, v.sy * 0.24);
416:     ctx.stroke();
417:     // bore glow
418:     ctx.shadowColor = 'rgba(255,122,26,.5)';
419:     ctx.shadowBlur = 9;
420:     ctx.strokeStyle = '#ff7a1a';
421:     ctx.lineWidth = 2.6;
422:     ctx.stroke();
423:     ctx.shadowBlur = 0;
424: 
425:     // rod joints
426:     const jointEvery = 3;
427:     let acc = 0;
428:     for (let i = 1; i < path.length; i++) {
429:       const a = path[i - 1], b = path[i];
430:       const len = Math.hypot(b.x - a.x, b.d - a.d);
431:       acc += len;
432:       if (acc >= jointEvery) {
433:         acc = 0;
434:         const x = this.X(b.x), y = this.Y(b.d);
435:         const dx = this.X(b.x) - this.X(a.x), dy = this.Y(b.d) - this.Y(a.d);
436:         const ang = Math.atan2(dy, dx) + Math.PI / 2;
437:         ctx.strokeStyle = 'rgba(255,200,140,.5)';
438:         ctx.lineWidth = 1;
439:         ctx.beginPath();
440:         ctx.moveTo(x - Math.cos(ang) * 3, y - Math.sin(ang) * 3);
441:         ctx.lineTo(x + Math.cos(ang) * 3, y + Math.sin(ang) * 3);
442:         ctx.stroke();
443:       }
444:     }
445: 
446:     // moving mud specks inside bore
447:     if (game.stage === 'pilot' || game.stage === 'mud' || game.stage === 'ream' || game.stage === 'pull') {
448:       const n = Math.min(40, Math.max(8, Math.floor(path.length / 2)));
449:       for (let i = 0; i < n; i++) {
450:         const idx = (i * 3 + Math.floor(t * 5)) % path.length;
451:         const p = screen[idx];
452:         ctx.fillStyle = `rgba(255,210,150,${0.18 + 0.12 * Math.sin(t * 4 + i)})`;
453:         ctx.beginPath(); ctx.arc(p.x, p.y, 1.4, 0, TAU); ctx.fill();
454:       }
455:     }
456: 
457:     // sonde pulses
458:     if (game.stage === 'pilot' && game.head) {
459:       const hx = this.X(game.head.x), hy = this.Y(game.head.d);
460:       for (let i = 0; i < 3; i++) {
461:         const ph = (t * 0.7 + i / 3) % 1;
462:         ctx.strokeStyle = `rgba(94,214,255,${(1 - ph) * 0.25})`;
463:         ctx.lineWidth = 1.2;
464:         ctx.beginPath(); ctx.arc(hx, hy, 8 + ph * 30, 0, TAU); ctx.stroke();
465:       }
466:     }
467:     ctx.restore();
468:   }
469: 
470:   drawPits(ctx, v, game) {
471:     const c = game.contract;
472:     const drawPit = (x, label, isExit) => {
473:       const sx = this.X(x);
474:       if (sx < -80 || sx > this.w + 80) return;
475:       const half = Math.max(13, (isExit ? 1.6 : 2.2) * v.sx);
476:       const pitDepth = isExit ? c.exitDepth + 0.45 : 1.25;
477:       const depth = Math.min(pitDepth * v.sy, this.h - v.groundY - 10);
478:       ctx.save();
479:       // excavation
480:       const pg = ctx.createLinearGradient(0, v.groundY, 0, v.groundY + depth);
481:       pg.addColorStop(0, '#241a12');
482:       pg.addColorStop(0.5, '#171009');
483:       pg.addColorStop(1, '#0a0705');
484:       ctx.fillStyle = pg;
485:       ctx.beginPath();
486:       ctx.moveTo(sx - half * 1.18, v.groundY - 2);
487:       ctx.lineTo(sx + half * 1.18, v.groundY - 2);
488:       ctx.lineTo(sx + half, v.groundY + depth);
489:       ctx.lineTo(sx - half, v.groundY + depth);
490:       ctx.closePath(); ctx.fill();
491:       // soil rim
492:       ctx.strokeStyle = 'rgba(180,140,95,.5)';
493:       ctx.lineWidth = 2;
494:       ctx.beginPath(); ctx.moveTo(sx - half, v.groundY + depth); ctx.lineTo(sx + half, v.groundY + depth); ctx.stroke();
495:       // shoring / walls
496:       ctx.strokeStyle = 'rgba(190,150,100,.32)';
497:       ctx.lineWidth = 1.4;
498:       ctx.beginPath();
499:       ctx.moveTo(sx - half * 1.08, v.groundY); ctx.lineTo(sx - half, v.groundY + depth);
500:       ctx.moveTo(sx + half * 1.08, v.groundY); ctx.lineTo(sx + half, v.groundY + depth);
501:       ctx.stroke();
502:       for (let d = 0.6; d < depth / v.sy; d += 0.9) {
503:         const yy = v.groundY + d * v.sy;
504:         ctx.strokeStyle = 'rgba(180,145,100,.18)';
505:         ctx.beginPath(); ctx.moveTo(sx - half * 1.02, yy); ctx.lineTo(sx + half * 1.02, yy); ctx.stroke();
506:       }
507:       // ladder in exit shaft
508:       if (isExit && depth > 40) {
509:         ctx.strokeStyle = 'rgba(200,205,200,.28)';
510:         ctx.lineWidth = 1;
511:         const lx = sx + half * 0.55;
512:         ctx.beginPath(); ctx.moveTo(lx, v.groundY + 4); ctx.lineTo(lx, v.groundY + depth - 4); ctx.stroke();
513:         for (let yy = v.groundY + 10; yy < v.groundY + depth - 6; yy += 9) {
514:           ctx.beginPath(); ctx.moveTo(lx - 3, yy); ctx.lineTo(lx + 3, yy); ctx.stroke();
515:         }
516:       }
517:       // target at exit
518:       if (isExit) {
519:         const ty = this.Y(c.exitDepth);
520:         ctx.strokeStyle = 'rgba(94,214,255,.85)';
521:         ctx.lineWidth = 1.5;
522:         ctx.beginPath(); ctx.arc(sx, ty, 9, 0, TAU); ctx.stroke();
523:         ctx.beginPath(); ctx.arc(sx, ty, 3, 0, TAU); ctx.stroke();
524:       }
525:       // label
526:       ctx.fillStyle = 'rgba(7,16,23,.86)';
527:       ctx.strokeStyle = isExit ? 'rgba(94,214,255,.5)' : 'rgba(255,177,92,.45)';
528:       ctx.lineWidth = 1;
529:       const tw = 44, th = 15;
530:       const ly = Math.min(v.groundY + depth + 6, this.h - 22);
531:       this.rr(ctx, sx - tw / 2, ly, tw, th, 4);
532:       ctx.fill(); ctx.stroke();
533:       ctx.fillStyle = isExit ? '#9fe6ff' : '#ffc27a';
534:       ctx.font = 'bold 7px system-ui';
535:       ctx.textAlign = 'center';
536:       ctx.fillText(label, sx, ly + 10);
537:       ctx.restore();
538:     };
539:     drawPit(0, 'ВХОД', false);
540:     drawPit(c.length, 'ВЫХОД', true);
541:   }
