543:   drawEquipment(ctx, v, game, t) {
544:     const gy = v.groundY;
545:     const s = v.narrow ? 0.72 : 1;
546:     const entry = this.X(0);
547:     const exit = this.X(game.contract.length);
548:     ctx.save();
549: 
550:     // gravel pad
551:     if (game.stage === 'prep') {
552:       const padL = this.X(v.narrow ? -12 : -17), padR = this.X(6);
553:       ctx.fillStyle = 'rgba(104,99,88,.42)';
554:       ctx.fillRect(padL, gy - 1, Math.max(0, padR - padL), 6);
555:     }
556: 
557:     // fence behind
558:     this.drawFence(ctx, v, game, s);
559: 
560:     // trailer + truck (wide only)
561:     if (!v.narrow) {
562:       this.drawTrailer(ctx, this.X(-23), gy, s);
563:       this.drawTruck(ctx, this.X(-18.5), gy, s);
564:     }
565: 
566:     // water tank + mud tank
567:     if (!v.narrow) this.drawWaterTank(ctx, this.X(-14.5), gy, s);
568:     this.drawMudTank(ctx, this.X(v.narrow ? -10.6 : -11.3), gy, s, t);
569: 
570:     // rod rack
571:     this.drawRodRack(ctx, this.X(v.narrow ? -7.4 : -7.8), gy, s);
572: 
573:     // spoil pile
574:     this.drawSpoil(ctx, this.X(4.4), gy, s);
575: 
576:     // rig
577:     this.drawRig(ctx, this.X(v.narrow ? -5.1 : -5.2), entry, gy, s, t, game);
578: 
579:     // exit equipment
580:     if (!v.narrow && exit < this.w + 90) {
581:       this.drawExcavator(ctx, exit + 30 * s, gy, s * 0.8);
582:     }
583:     this.cone(ctx, exit - 10 * s, gy, s);
584:     this.cone(ctx, exit + 10 * s, gy, s);
585:     this.cone(ctx, entry - 16 * s, gy, s);
586:     this.cone(ctx, entry + 29 * s, gy, s);
587:     ctx.restore();
588:   }
