612:     ctx.fillStyle = '#c9d2d3';
613:     this.rr(ctx, x - 34 * s, gy - 44 * s, 68 * s, 40 * s, 3 * s); ctx.fill();
614:     ctx.fillStyle = '#8f9b9e';
615:     ctx.fillRect(x - 34 * s, gy - 50 * s, 68 * s, 7 * s);
616:     ctx.fillStyle = '#33434c';
617:     this.rr(ctx, x - 24 * s, gy - 34 * s, 18 * s, 18 * s, 2 * s); ctx.fill();
618:     this.rr(ctx, x + 4 * s, gy - 34 * s, 16 * s, 25 * s, 2 * s); ctx.fill();
619:     ctx.fillStyle = '#b9c2c3';
620:     ctx.fillRect(x - 28 * s, gy - 4 * s, 56 * s, 4 * s);
621:     ctx.fillStyle = '#1a2226';
622:     ctx.beginPath(); ctx.arc(x - 20 * s, gy, 4 * s, 0, TAU); ctx.fill();
623:     ctx.beginPath(); ctx.arc(x + 20 * s, gy, 4 * s, 0, TAU); ctx.fill();
624:     ctx.fillStyle = 'rgba(255,122,26,.9)';
