774:   drawRig(ctx, x, entry, gy, s, t, game) {
775:     ctx.save();
776:     const bob = Math.sin(t * 1.35) * 0.35 * s;
777:     const y = gy + bob;
778: 
779:     // ground shadow
780:     ctx.fillStyle = 'rgba(0,0,0,.32)';
781:     ctx.beginPath(); ctx.ellipse(x - 12 * s, gy + 1.5 * s, 76 * s, 5.5 * s, 0, 0, TAU); ctx.fill();
782: 
783:     // crawler undercarriage
784:     const trX = x - 76 * s, trY = gy - 27 * s, trW = 130 * s, trH = 27 * s;
785:     const track = ctx.createLinearGradient(0, trY, 0, trY + trH);
786:     track.addColorStop(0, '#3b4144');
787:     track.addColorStop(0.45, '#1c2022');
788:     track.addColorStop(1, '#0e1112');
789:     ctx.fillStyle = track;
790:     this.rr(ctx, trX, trY, trW, trH, 12 * s); ctx.fill();
791: 
792:     // track links and road wheels
793:     ctx.save();
794:     this.rr(ctx, trX + s, trY + s, trW - 2 * s, trH - 2 * s, 11 * s); ctx.clip();
795:     ctx.strokeStyle = 'rgba(120,130,135,.42)';
796:     ctx.lineWidth = 1.1 * s;
797:     for (let i = 0; i < 26; i++) {
798:       const lx = trX + 5 * s + i * 5 * s;
799:       ctx.beginPath();
800:       ctx.moveTo(lx, trY + s); ctx.lineTo(lx - 2 * s, trY + 5 * s);
801:       ctx.moveTo(lx, trY + trH - s); ctx.lineTo(lx - 2 * s, trY + trH - 5 * s);
802:       ctx.stroke();
803:     }
804:     for (let i = 0; i < 5; i++) {
805:       const wx = trX + 30 * s + i * 17 * s;
806:       const wy = gy - 10 * s;
807:       ctx.fillStyle = '#242a2d';
808:       ctx.beginPath(); ctx.arc(wx, wy, 7.4 * s, 0, TAU); ctx.fill();
809:       ctx.fillStyle = '#5c666b';
810:       ctx.beginPath(); ctx.arc(wx, wy, 3.2 * s, 0, TAU); ctx.fill();
811:       ctx.fillStyle = '#252b2e';
812:       ctx.beginPath(); ctx.arc(wx, wy, 1.4 * s, 0, TAU); ctx.fill();
813:     }
814:     [[trX + 14 * s, 9 * s], [trX + trW - 14 * s, 8 * s]].forEach(([sx, rad]) => {
815:       ctx.fillStyle = '#2b3235';
816:       ctx.beginPath(); ctx.arc(sx, gy - 12 * s, rad, 0, TAU); ctx.fill();
817:       ctx.strokeStyle = '#68747a'; ctx.lineWidth = 1.6 * s;
818:       ctx.beginPath(); ctx.arc(sx, gy - 12 * s, rad * 0.55, 0, TAU); ctx.stroke();
819:     });
820:     ctx.restore();
821:     ctx.strokeStyle = 'rgba(140,150,155,.32)';
822:     ctx.lineWidth = 1.2 * s;
823:     this.rr(ctx, trX, trY, trW, trH, 12 * s); ctx.stroke();
824: 
825:     // chassis / black belly
826:     ctx.fillStyle = '#171c1f';
827:     this.rr(ctx, x - 72 * s, gy - 34 * s, 118 * s, 12 * s, 3 * s); ctx.fill();
828:     ctx.fillStyle = '#2a3134';
829:     ctx.fillRect(x - 68 * s, gy - 26 * s, 110 * s, 3 * s);
830: 
831:     // rear counterweight / engine cover
832:     ctx.fillStyle = '#111516';
833:     this.rr(ctx, x - 82 * s, y - 60 * s, 16 * s, 38 * s, 5 * s); ctx.fill();
834:     ctx.fillStyle = 'rgba(255,255,255,.08)';
835:     ctx.fillRect(x - 80 * s, y - 56 * s, 2 * s, 29 * s);
836: 
837:     // engine hood
838:     const hood = ctx.createLinearGradient(0, y - 66 * s, 0, y - 23 * s);
839:     hood.addColorStop(0, '#ffd84a');
840:     hood.addColorStop(0.48, '#f7bb18');
841:     hood.addColorStop(1, '#d58c00');
842:     ctx.fillStyle = hood;
843:     ctx.beginPath();
844:     ctx.moveTo(x - 68 * s, y - 24 * s);
845:     ctx.lineTo(x - 68 * s, y - 55 * s);
846:     ctx.quadraticCurveTo(x - 68 * s, y - 65 * s, x - 56 * s, y - 65 * s);
847:     ctx.lineTo(x - 21 * s, y - 65 * s);
848:     ctx.quadraticCurveTo(x - 7 * s, y - 65 * s, x - 3 * s, y - 52 * s);
849:     ctx.lineTo(x + s, y - 32 * s);
850:     ctx.lineTo(x + s, y - 24 * s);
851:     ctx.closePath(); ctx.fill();
852: 
853:     // hood top highlight
854:     ctx.strokeStyle = 'rgba(255,248,190,.55)';
855:     ctx.lineWidth = 1.4 * s;
856:     ctx.beginPath();
857:     ctx.moveTo(x - 57 * s, y - 64 * s);
858:     ctx.lineTo(x - 22 * s, y - 64 * s);
859:     ctx.quadraticCurveTo(x - 9 * s, y - 64 * s, x - 5 * s, y - 53 * s);
860:     ctx.stroke();
861: 
862:     // green speed stripe
863:     ctx.fillStyle = '#2f7d3a';
864:     ctx.beginPath();
865:     ctx.moveTo(x - 69 * s, y - 38 * s);
866:     ctx.bezierCurveTo(x - 44 * s, y - 36 * s, x - 20 * s, y - 33 * s, x - 2 * s, y - 27 * s);
867:     ctx.lineTo(x - 2 * s, y - 23 * s);
868:     ctx.bezierCurveTo(x - 24 * s, y - 30 * s, x - 47 * s, y - 32 * s, x - 69 * s, y - 33 * s);
869:     ctx.closePath(); ctx.fill();
870:     ctx.strokeStyle = 'rgba(20,55,25,.55)';
871:     ctx.lineWidth = 0.8 * s;
872:     ctx.stroke();
873: 
874:     // black decal band / model
875:     ctx.fillStyle = 'rgba(18,22,20,.9)';
876:     ctx.beginPath();
877:     ctx.moveTo(x - 66 * s, y - 33 * s);
878:     ctx.lineTo(x - 34 * s, y - 33 * s);
879:     ctx.lineTo(x - 39 * s, y - 25 * s);
880:     ctx.lineTo(x - 68 * s, y - 25 * s);
881:     ctx.closePath(); ctx.fill();
882:     ctx.fillStyle = '#f8fbf4';
883:     ctx.font = `italic 900 ${8 * s}px system-ui`;
884:     ctx.textAlign = 'left';
885:     ctx.fillText('D24', x - 62 * s, y - 27.5 * s);
886: 
887:     // brand
888:     ctx.fillStyle = 'rgba(22,22,16,.92)';
889:     ctx.font = `800 ${7.5 * s}px system-ui`;
890:     ctx.fillText('AVTO-M', x - 62 * s, y - 49 * s);
891:     ctx.font = `600 ${4.6 * s}px system-ui`;
892:     ctx.fillText('NAVIGATOR', x - 30 * s, y - 48 * s);
893: 
894:     // hood vents and panel seams
895:     ctx.fillStyle = 'rgba(45,32,8,.5)';
896:     for (let i = 0; i < 5; i++) ctx.fillRect(x - 58 * s + i * 4.2 * s, y - 56 * s, 2.2 * s, 8 * s);
897:     ctx.strokeStyle = 'rgba(90,60,10,.35)';
898:     ctx.lineWidth = 0.8 * s;
899:     ctx.beginPath(); ctx.moveTo(x - 4 * s, y - 50 * s); ctx.lineTo(x - 4 * s, y - 26 * s); ctx.stroke();
900:     ctx.beginPath(); ctx.moveTo(x - 68 * s, y - 57 * s); ctx.lineTo(x - 58 * s, y - 57 * s); ctx.stroke();
901: 
902:     // warning decals
903:     ctx.fillStyle = 'rgba(245,245,235,.85)';
904:     ctx.fillRect(x - 13 * s, y - 59 * s, 3 * s, 3 * s);
905:     ctx.fillStyle = '#c8341f';
906:     ctx.fillRect(x - 12.5 * s, y - 58.5 * s, 2 * s, 2 * s);
907: 
908:     // cab
