1083:   drawCrew(ctx, v, game, t) {
1084:     if (!game.crew) return;
1085:     const active = {
1086:       prep: ['foreman'], pilot: ['operator', 'locator'], mud: ['mud', 'foreman'],
1087:       ream: ['operator', 'mechanic'], pull: ['operator', 'foreman'], results: []
1088:     }[game.stage] || [];
1089:     const pos = this.crewLayout(game, v);
1090:     const s = v.narrow ? 0.6 : 0.82;
1091:     const order = ['mud', 'mechanic', 'foreman', 'operator', 'locator'];
1092:     for (const id of order) {
1093:       const m = game.crew[id];
1094:       if (!m) continue;
1095:       const role = ROLES.find(r => r.id === id);
1096:       const p = pos[id];
1097:       if (!p || p.x < -60 || p.x > this.w + 60) continue;
1098:       const isActive = active.includes(id);
1099:       this.drawWorker(ctx, p.x, v.groundY, s, {
1100:         role, name: m.name, active: isActive, t,
1101:         pose: this.poseFor(id, game, t),
1102:         label: !this.demo && isActive,
1103:         moving: id === 'locator' && game.stage === 'pilot'
1104:       });
1105:     }
1106: 
1107:     // sonde link locator -> head
1108:     if (game.stage === 'pilot' && game.head) {
1109:       const lp = pos.locator;
1110:       const hx = this.X(game.head.x), hy = this.Y(game.head.d);
1111:       ctx.save();
1112:       ctx.strokeStyle = 'rgba(94,214,255,.28)';
1113:       ctx.lineWidth = 1;
1114:       ctx.setLineDash([3, 5]);
1115:       ctx.beginPath();
1116:       ctx.moveTo(lp.x, v.groundY - 30 * s);
1117:       ctx.lineTo(hx, hy);
1118:       ctx.stroke();
1119:       ctx.setLineDash([]);
1120:       const pulse = 0.5 + Math.sin(t * 4) * 0.5;
1121:       ctx.fillStyle = `rgba(94,214,255,${0.35 + pulse * 0.4})`;
1122:       ctx.beginPath(); ctx.arc(hx, hy, 3.4, 0, TAU); ctx.fill();
1123:       ctx.restore();
1124:     }
1125:   }
