1267:   pointAtX(path, x) {
1268:     if (!path || !path.length) return { x, d: 0 };
1269:     if (x <= path[0].x) return path[0];
1270:     for (let i = 1; i < path.length; i++) {
1271:       if (path[i].x >= x) {
1272:         const a = path[i - 1], b = path[i];
1273:         const t = (x - a.x) / Math.max(0.0001, b.x - a.x);
1274:         return { x, d: lerp(a.d, b.d, t) };
1275:       }
1276:     }
1277:     return path[path.length - 1];
1278:   }
