1288:       const x = this.X(game.head.x), y = this.Y(game.head.d);
1289:       const ang = this.toolAngle(v, game.head.pitch || 0);
1290:       ctx.save();
1291:       ctx.translate(x, y);
1292:       ctx.rotate(ang);
1293:       const scale = clamp(v.sy / 26, 0.85, 1.5);
1294:       // body
1295:       ctx.fillStyle = '#2f3a3f';
1296:       this.rr(ctx, -20 * scale, -5 * scale, 20 * scale, 10 * scale, 3 * scale); ctx.fill();
1297:       ctx.fillStyle = '#58656a';
1298:       this.rr(ctx, -20 * scale, -4 * scale, 18 * scale, 3 * scale, 1.5 * scale); ctx.fill();
1299:       // orange band
1300:       ctx.fillStyle = '#ff7a1a';
1301:       ctx.fillRect(-13 * scale, -5 * scale, 3 * scale, 10 * scale);
1302:       // nose
1303:       ctx.fillStyle = '#aab4b6';
1304:       ctx.beginPath();
1305:       ctx.moveTo(0, -5 * scale);
