121:   drawSky(ctx, v, t, game) {
122:     const g = ctx.createLinearGradient(0, 0, 0, v.groundY);
123:     g.addColorStop(0, '#08151f');
124:     g.addColorStop(0.4, '#173444');
125:     g.addColorStop(0.72, '#3f5c63');
126:     g.addColorStop(0.92, '#a47a52');
127:     g.addColorStop(1, '#c3945f');
128:     ctx.fillStyle = g;
129:     ctx.fillRect(0, 0, this.w, v.groundY + 2);
130: 
131:     const sunX = this.w * 0.79, sunY = v.groundY * 0.35;
132:     const sun = ctx.createRadialGradient(sunX, sunY, 0, sunX, sunY, this.w * 0.22);
133:     sun.addColorStop(0, 'rgba(255,214,160,.55)');
134:     sun.addColorStop(0.35, 'rgba(255,180,110,.14)');
135:     sun.addColorStop(1, 'rgba(255,170,100,0)');
136:     ctx.fillStyle = sun;
137:     ctx.fillRect(0, 0, this.w, v.groundY);
138: 
139:     ctx.fillStyle = 'rgba(255,236,205,.55)';
140:     ctx.beginPath(); ctx.arc(sunX, sunY, Math.max(12, this.w * 0.018), 0, TAU); ctx.fill();
141: 
142:     // distant hills
143:     const hill = (base, amp, freq, color) => {
144:       ctx.beginPath();
145:       ctx.moveTo(0, v.groundY);
146:       for (let x = 0; x <= this.w + 20; x += 24) {
147:         ctx.lineTo(x, base - Math.sin(x * freq + 1.4) * amp - Math.sin(x * freq * 2.3) * amp * 0.3);
148:       }
149:       ctx.lineTo(this.w, v.groundY); ctx.closePath();
150:       ctx.fillStyle = color; ctx.fill();
151:     };
152:     hill(v.groundY - 2, 9, 0.007, '#193642');
153:     hill(v.groundY + 1, 5, 0.012, '#1c3b3e');
154: 
155:     // clouds
156:     ctx.fillStyle = 'rgba(220,230,225,.09)';
157:     [[0.16, 0.18, 70], [0.38, 0.1, 48], [0.62, 0.22, 62], [0.9, 0.14, 40]].forEach(([px, py, s]) => {
158:       const cx = px * this.w, cy = py * v.groundY;
159:       ctx.beginPath();
160:       ctx.ellipse(cx, cy, s, s * 0.22, 0, 0, TAU);
161:       ctx.ellipse(cx + s * 0.5, cy - s * 0.08, s * 0.5, s * 0.18, 0, 0, TAU);
162:       ctx.fill();
163:     });
164: 
165:     // horizon haze
166:     const haze = ctx.createLinearGradient(0, v.groundY - 40, 0, v.groundY);
167:     haze.addColorStop(0, 'rgba(255,190,130,0)');
168:     haze.addColorStop(1, 'rgba(255,190,130,.12)');
169:     ctx.fillStyle = haze;
170:     ctx.fillRect(0, v.groundY - 40, this.w, 40);
171:   }
