280:   drawUtilities(ctx, v, game, t) {
281:     const utils = game.utilities || [];
282:     for (const u of utils) {
283:       const x = this.X(u.x);
284:       if (x < -60 || x > this.w + 60) continue;
285:       const y = this.Y(u.depth);
286:       if (y > this.h + 20) continue;
287:       const known = u.revealed !== false;
288:       if (!known && !u.detected) continue;
289:       const col = u.color || UTILITY_TYPES[u.type]?.color || '#5ed6ff';
290:       const r = Math.max(5.5, (u.size || 0.15) * v.sy * 0.9);
291:       const hz = Math.max(13, u.clearance * v.sx);
292:       const pulse = 0.5 + Math.sin(t * 3 + u.x) * 0.5;
293: 
294:       // hazard column
295:       ctx.save();
296:       const band = ctx.createLinearGradient(0, v.groundY, 0, y + r * 2);
297:       band.addColorStop(0, known ? 'rgba(255,120,90,.02)' : 'rgba(255,90,90,.02)');
298:       band.addColorStop(1, known ? 'rgba(255,120,90,.12)' : 'rgba(255,90,90,.16)');
299:       ctx.fillStyle = band;
300:       ctx.fillRect(x - hz, v.groundY, hz * 2, Math.max(8, y + r * 2 - v.groundY));
301:       ctx.strokeStyle = known ? `rgba(255,170,120,${0.16 + pulse * 0.1})` : `rgba(255,90,90,${0.25 + pulse * 0.2})`;
302:       ctx.setLineDash([3, 5]);
303:       ctx.lineWidth = 1;
304:       ctx.beginPath(); ctx.moveTo(x, v.groundY); ctx.lineTo(x, y + r * 2.2); ctx.stroke();
305:       ctx.setLineDash([]);
306: 
307:       // clearance ring
308:       ctx.strokeStyle = known ? 'rgba(255,150,110,.28)' : 'rgba(255,90,90,.4)';
309:       ctx.setLineDash([4, 4]);
310:       ctx.beginPath();
311:       ctx.ellipse(x, y, Math.max(r * 2.1, hz * 0.9), Math.max(r * 2.1, (u.clearance || 0.6) * v.sy), 0, 0, TAU);
312:       ctx.stroke();
313:       ctx.setLineDash([]);
314: 
315:       // pipe / cable
316:       ctx.fillStyle = 'rgba(8,12,14,.9)';
317:       ctx.beginPath(); ctx.arc(x, y, r + 3, 0, TAU); ctx.fill();
318:       const pg = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, 1, x, y, r + 1);
319:       pg.addColorStop(0, this.lighten(col, 40));
320:       pg.addColorStop(1, col);
321:       ctx.fillStyle = pg;
322:       ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
323:       ctx.strokeStyle = 'rgba(0,0,0,.55)';
324:       ctx.lineWidth = 1.5;
325:       ctx.beginPath(); ctx.arc(x, y, r * 0.55, 0, TAU); ctx.stroke();
326: 
327:       if (!known) {
328:         ctx.fillStyle = 'rgba(255,120,100,.95)';
329:         ctx.font = 'bold 12px system-ui';
330:         ctx.textAlign = 'center';
331:         ctx.fillText('?', x, y - r - 8);
332:       } else {
333:         // surface marker
334:         ctx.fillStyle = col;
335:         ctx.beginPath();
336:         ctx.moveTo(x, v.groundY - 12);
337:         ctx.lineTo(x + 4, v.groundY - 5);
338:         ctx.lineTo(x - 4, v.groundY - 5);
339:         ctx.closePath();
340:         ctx.fill();
341:         ctx.fillStyle = 'rgba(7,16,23,.85)';
342:         ctx.beginPath(); ctx.arc(x, v.groundY - 4, 3.4, 0, TAU); ctx.fill();
343:       }
344:       ctx.restore();
345:     }
346: 
347:     // active sonde proximity warn
348:     if (game.stage === 'pilot' && game.head) {
349:       for (const u of utils) {
350:         if (u.revealed === false) continue;
351:         if (u.hit) continue;
352:         const dx = u.x - game.head.x;
353:         if (dx > -2 && dx < 14) {
354:           const x = this.X(u.x), y = this.Y(u.depth);
355:           ctx.strokeStyle = `rgba(255,100,90,${0.18 + (0.5 + Math.sin(t * 3) * 0.5) * 0.16})`;
356:           ctx.lineWidth = 2;
357:           ctx.setLineDash([3, 6]);
358:           ctx.beginPath(); ctx.arc(x, y, Math.max(16, u.clearance * v.sy), 0, TAU); ctx.stroke();
359:           ctx.setLineDash([]);
360:         }
361:       }
362:     }
363:   }
