370:   drawDesign(ctx, v, game) {
371:     const c = game.contract;
372:     if (game.stage !== 'prep' && game.prep?.route === 'skip') return;
373:     const pts = game.design || c.design;
374:     ctx.save();
375:     ctx.strokeStyle = 'rgba(94,214,255,.72)';
376:     ctx.lineWidth = 1.6;
377:     ctx.setLineDash([8, 7]);
378:     ctx.beginPath();
379:     pts.forEach((p, i) => {
380:       const x = this.X(p.x), y = this.Y(p.d);
381:       i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
382:     });
383:     ctx.stroke();
384:     ctx.setLineDash([]);
385:     // direction arrows
386:     ctx.fillStyle = 'rgba(94,214,255,.8)';
387:     for (let i = 14; i < pts.length; i += 22) {
388:       const p = pts[i];
389:       const n = pts[Math.min(pts.length - 1, i + 2)];
390:       const x = this.X(p.x), y = this.Y(p.d);
391:       const ang = Math.atan2(this.Y(n.d) - y, this.X(n.x) - x);
392:       ctx.save();
393:       ctx.translate(x, y); ctx.rotate(ang);
394:       ctx.beginPath(); ctx.moveTo(4, 0); ctx.lineTo(-3, -3); ctx.lineTo(-3, 3); ctx.closePath(); ctx.fill();
395:       ctx.restore();
396:     }
397:     ctx.restore();
398:   }
