470:   drawPits(ctx, v, game) {
471:     const c = game.contract;
472:     const drawPit = (x, label, isExit) => {
473:       const sx = this.X(x);
474:       if (sx < -80 || sx > this.w + 80) return;
475:       const half = Math.max(13, (isExit ? 1.6 : 2.2) * v.sx);
476:       const pitDepth = isExit ? c.exitDepth + 0.45 : 1.25;
477:       const depth = Math.min(pitDepth * v.sy, this.h - v.groundY - 10);
478:       ctx.save();
479:       // excavation
480:       const pg = ctx.createLinearGradient(0, v.groundY, 0, v.groundY + depth);
481:       pg.addColorStop(0, '#241a12');
482:       pg.addColorStop(0.5, '#171009');
483:       pg.addColorStop(1, '#0a0705');
484:       ctx.fillStyle = pg;
485:       ctx.beginPath();
486:       ctx.moveTo(sx - half * 1.18, v.groundY - 2);
487:       ctx.lineTo(sx + half * 1.18, v.groundY - 2);
488:       ctx.lineTo(sx + half, v.groundY + depth);
489:       ctx.lineTo(sx - half, v.groundY + depth);
490:       ctx.closePath(); ctx.fill();
491:       // soil rim
492:       ctx.strokeStyle = 'rgba(180,140,95,.5)';
493:       ctx.lineWidth = 2;
494:       ctx.beginPath(); ctx.moveTo(sx - half, v.groundY + depth); ctx.lineTo(sx + half, v.groundY + depth); ctx.stroke();
495:       // shoring / walls
496:       ctx.strokeStyle = 'rgba(190,150,100,.32)';
497:       ctx.lineWidth = 1.4;
498:       ctx.beginPath();
499:       ctx.moveTo(sx - half * 1.08, v.groundY); ctx.lineTo(sx - half, v.groundY + depth);
500:       ctx.moveTo(sx + half * 1.08, v.groundY); ctx.lineTo(sx + half, v.groundY + depth);
501:       ctx.stroke();
502:       for (let d = 0.6; d < depth / v.sy; d += 0.9) {
503:         const yy = v.groundY + d * v.sy;
504:         ctx.strokeStyle = 'rgba(180,145,100,.18)';
505:         ctx.beginPath(); ctx.moveTo(sx - half * 1.02, yy); ctx.lineTo(sx + half * 1.02, yy); ctx.stroke();
506:       }
507:       // ladder in exit shaft
508:       if (isExit && depth > 40) {
509:         ctx.strokeStyle = 'rgba(200,205,200,.28)';
510:         ctx.lineWidth = 1;
511:         const lx = sx + half * 0.55;
512:         ctx.beginPath(); ctx.moveTo(lx, v.groundY + 4); ctx.lineTo(lx, v.groundY + depth - 4); ctx.stroke();
513:         for (let yy = v.groundY + 10; yy < v.groundY + depth - 6; yy += 9) {
514:           ctx.beginPath(); ctx.moveTo(lx - 3, yy); ctx.lineTo(lx + 3, yy); ctx.stroke();
515:         }
516:       }
517:       // target at exit
518:       if (isExit) {
519:         const ty = this.Y(c.exitDepth);
520:         ctx.strokeStyle = 'rgba(94,214,255,.85)';
521:         ctx.lineWidth = 1.5;
522:         ctx.beginPath(); ctx.arc(sx, ty, 9, 0, TAU); ctx.stroke();
523:         ctx.beginPath(); ctx.arc(sx, ty, 3, 0, TAU); ctx.stroke();
524:       }
525:       // label
526:       ctx.fillStyle = 'rgba(7,16,23,.86)';
527:       ctx.strokeStyle = isExit ? 'rgba(94,214,255,.5)' : 'rgba(255,177,92,.45)';
528:       ctx.lineWidth = 1;
529:       const tw = 44, th = 15;
530:       const ly = Math.min(v.groundY + depth + 6, this.h - 22);
531:       this.rr(ctx, sx - tw / 2, ly, tw, th, 4);
532:       ctx.fill(); ctx.stroke();
533:       ctx.fillStyle = isExit ? '#9fe6ff' : '#ffc27a';
534:       ctx.font = 'bold 7px system-ui';
535:       ctx.textAlign = 'center';
536:       ctx.fillText(label, sx, ly + 10);
537:       ctx.restore();
538:     };
539:     drawPit(0, 'ВХОД', false);
540:     drawPit(c.length, 'ВЫХОД', true);
541:   }
