590:   drawFence(ctx, v, game, s) {
591:     const gy = v.groundY;
592:     const x0 = Math.max(-10, v.x0), x1 = Math.min(game.contract.length + 3, v.x1);
593:     if (x1 <= x0) return;
594:     const step = 3.2;
595:     ctx.save();
596:     ctx.strokeStyle = 'rgba(180,195,200,.18)';
597:     ctx.lineWidth = 1;
598:     for (let x = Math.ceil(x0 / step) * step; x < x1; x += step) {
599:       const sx = this.X(x);
600:       ctx.beginPath(); ctx.moveTo(sx, gy - 17 * s); ctx.lineTo(sx, gy - 1); ctx.stroke();
601:     }
602:     const a = this.X(Math.ceil(x0 / step) * step), b = this.X(x1);
603:     ctx.strokeStyle = 'rgba(180,195,200,.11)';
604:     for (let k = 0; k < 3; k++) {
605:       ctx.beginPath(); ctx.moveTo(a, gy - (5 + k * 5) * s); ctx.lineTo(b, gy - (5 + k * 5) * s); ctx.stroke();
606:     }
607:     ctx.restore();
608:   }
