942:   updatePilot(dt) {
943:     const c = this.contract;
944:     const prevX = this.head.x;
945:     const thrust = (this.holds.feed ? 1 : this.input.auto ? 0.55 : 0);
946:     const steer = (this.holds.up ? 1 : 0) - (this.holds.down ? 1 : 0);
947:     const op = this.crew.operator;
948:     const locatorAssist = op.mods.locatorAssist
949:       ? 0.86 + this.crew.locator.effective * 0.045
950:       : 1;
951:     const steerFactor = (0.76 + op.effective * 0.055) * (op.mods.steer || 1) * locatorAssist;
952:     const steerEffect = this.input.rot ? 0.05 : 1;
953:     const pitchRate = 31 * steerFactor * steerEffect;
954: 
955:     this.head.pitch = clamp(this.head.pitch + steer * pitchRate * dt, -34, 34);
956:     const layer = c.layers.find(l => this.head.d >= l.top && this.head.d < l.bottom);
957:     const hardness = layer?.hardness || 1;
958:     const rotationSpeed = this.input.rot ? 1 : 0.55;
959:     const speed = thrust * 2.35 * (SOILS[c.soil].speed / hardness) * (0.84 + op.effective * 0.045) * rotationSpeed;
960:     const rad = this.head.pitch * Math.PI / 180;
961:     this.head.x += Math.cos(rad) * speed * dt;
962:     this.head.d += Math.sin(rad) * speed * dt;
963:     this.head.d = clamp(this.head.d, 0.55, 9.6);
964:     if (this.head.x < 0) this.head.x = 0;
965:     if (this.head.d <= 0.56 && this.head.pitch < 0) this.head.pitch = 0;
966: 
967:     if (this.head.x - (this.path[this.path.length - 1]?.x || 0) > 0.35) {
968:       this.path.push({ x: this.head.x, d: this.head.d });
969:     }
970: 
971:     // sonde detection of unknown utilities
972:     const loc = this.crew.locator;
973:     const range = 5 + loc.effective * 2.7 * (loc.mods.detect || 1);
974:     for (const u of this.utilities) {
975:       if (!u.revealed && !u.detected && Math.abs(u.x - this.head.x) < range) {
976:         u.detected = true;
977:         this.addLog('locator', `Неизвестная сеть впереди, ${Math.round(u.x - this.head.x)} м. Иду по сигналу — снизь подачу.`, 'alert');
978:         toast('Локатор: неизвестная коммуникация на трассе', 'warn');
979:         sound.warn();
980:       }
981:     }
982: 
983:     // utility crossing
984:     for (const u of this.utilities) {
985:       if (u.hit) continue;
986:       if (prevX < u.x && this.head.x >= u.x) {
987:         if (Math.abs(this.head.d - u.depth) < u.clearance) this.strike(u);
988:       }
989:     }
990: 
991:     // deviation accounting
992:     const dev = this.head.d - designDepthAt(c, this.head.x);
993:     this.stats.devSum += Math.abs(dev) * Math.max(0.01, this.head.x - prevX);
994:     this.stats.devSamples += Math.max(0.01, this.head.x - prevX);
995:     this.stats.devMax = Math.max(this.stats.devMax, Math.abs(dev));
996: 
997:     // pressure
998:     const mix = MIXES[this.prep.mud] || MIXES.bentonite;
999:     const win = this.pressureWindow();
1000:     const target = 24 + this.head.d * 3.6 + thrust * 26 + SOILS[c.soil].mud * 0.5;
1001:     this.pressure = lerp(this.pressure, target, 1 - Math.exp(-dt * 2.1));
1002:     if (this.pressure > win.high) {
1003:       const severity = (this.pressure - win.high) / 12;
1004:       this.fracRisk += dt * severity * (this.head.d < 3.2 ? 15 : 4.5);
1005:       this.stats.mudQuality = clamp(this.stats.mudQuality - dt * severity * 0.5, 0, 100);
1006:     } else {
1007:       this.fracRisk = Math.max(0, this.fracRisk - dt * 4);
1008:     }
1009:     if (this.fracRisk >= 100) this.fracOut();
1010: 
1011:     // rod wear
1012:     if (thrust > 0.72 && this.input.rot) {
1013:       const wearFactor = (op.mods.wear || 1) * (this.crew.mechanic.mods.wear || 1) * (1.18 - this.crew.mechanic.effective * 0.035);
1014:       this.wear += dt * 2.0 * wearFactor * (1 + Math.abs(dev) * 0.18);
1015:       if (this.wear >= 100) this.replaceRod();
1016:     }
1017: 
1018:     // vent cooldown
1019:     if (this.ventCd > 0) {
1020:       this.ventCd -= dt;
1021:       if (this.ventCd <= 0 && this.ventBtn) {
1022:         this.ventBtn.disabled = false;
1023:         this.ventBtn.textContent = 'Сбросить давление';
1024:       } else if (this.ventBtn) {
1025:         this.ventBtn.textContent = `Сброс через ${Math.ceil(this.ventCd)} с`;
1026:       }
1027:     }
1028: 
1029:     // live deck readouts
1030:     const feedVal = Math.round(thrust * 100);
1031:     this.setText($('feed-read'), `${feedVal}%`);
1032:     const mini = $('pilot-pressure-mini');
1033:     this.setText(mini, `${Math.round(this.pressure)}`);
1034:     const needle = $('pilot-needle');
1035:     if (needle) needle.style.left = `${clamp(this.pressure, 0, 100)}%`;
1036:     const band = $('pilot-band');
1037:     if (band) {
1038:       band.style.left = `${win.low}%`;
1039:       band.style.width = `${Math.max(4, win.high - win.low)}%`;
1040:     }
1041:     sound.setEngine(thrust > 0.05 ? 0.18 + thrust * 0.18 : 0.06);
1042: 
1043:     if (this.head.x >= c.length) {
1044:       this.head.x = c.length;
1045:       this.path.push({ x: c.length, d: this.head.d });
1046:       this.finishPilot();
1047:     }
1048:   }
