1189:   updateMud(dt) {
1190:     const sd = this.stageData;
1191:     const mix = MIXES[this.prep.mud] || MIXES.bentonite;
1192:     const w = this.mudWindow();
1193:     sd.time += dt;
1194:     sd.pumping = sd.flow > 8;
1195:     const wobble = Math.sin(this.simT * 1.35 + 1) * 2.6 + Math.sin(this.simT * 3.3) * 1.1;
1196:     const rush = this.crew.foreman.mods.rush ? 2.5 : 0;
1197:     const target = 12 + sd.flow * 0.62 + this.contract.maxDepth * 2.3 + SOILS[this.contract.soil].mud * 0.35 + wobble + rush;
1198:     sd.pressure = lerp(sd.pressure, target, 1 - Math.exp(-dt * 1.7));
1199: 
1200:     if (sd.pressure >= w.low && sd.pressure <= w.high) {
