774:   drawRig(ctx, x, entry, gy, s, t, game) {
775:     ctx.save();
776:     const bob = Math.sin(t * 1.35) * 0.35 * s;
777:     const y = gy + bob;
778: 
779:     // ground shadow
780:     ctx.fillStyle = 'rgba(0,0,0,.32)';
781:     ctx.beginPath(); ctx.ellipse(x - 12 * s, gy + 1.5 * s, 76 * s, 5.5 * s, 0, 0, TAU); ctx.fill();
782: 
783:     // crawler undercarriage
784:     const trX = x - 76 * s, trY = gy - 27 * s, trW = 130 * s, trH = 27 * s;
785:     const track = ctx.createLinearGradient(0, trY, 0, trY + trH);
786:     track.addColorStop(0, '#3b4144');
787:     track.addColorStop(0.45, '#1c2022');
788:     track.addColorStop(1, '#0e1112');
789:     ctx.fillStyle = track;
790:     this.rr(ctx, trX, trY, trW, trH, 12 * s); ctx.fill();
791: 
792:     // track links and road wheels
793:     ctx.save();
794:     this.rr(ctx, trX + s, trY + s, trW - 2 * s, trH - 2 * s, 11 * s); ctx.clip();
795:     ctx.strokeStyle = 'rgba(120,130,135,.42)';
796:     ctx.lineWidth = 1.1 * s;
797:     for (let i = 0; i < 26; i++) {
798:       const lx = trX + 5 * s + i * 5 * s;
799:       ctx.beginPath();
800:       ctx.moveTo(lx, trY + s); ctx.lineTo(lx - 2 * s, trY + 5 * s);
801:       ctx.moveTo(lx, trY + trH - s); ctx.lineTo(lx - 2 * s, trY + trH - 5 * s);
802:       ctx.stroke();
803:     }
804:     for (let i = 0; i < 5; i++) {
805:       const wx = trX + 30 * s + i * 17 * s;
