1054:   crewLayout(game, v) {
1055:     const c = game.contract;
1056:     const positions = {
1057:       operator: { x: this.X(-1.6) },
1058:       locator: { x: this.X(c.length * 0.44) },
1059:       mud: { x: this.X(v.narrow ? -9.4 : -10.3) },
1060:       mechanic: { x: this.X(v.narrow ? -6.6 : -7.1) },
1061:       foreman: { x: this.X(8.5) }
1062:     };
1063:     if (game.stage === 'pilot' && game.head) {
1064:       positions.locator.x = this.X(Math.min(c.length, game.head.x + 1.6));
1065:     }
1066:     if (game.stage === 'mud') {
1067:       positions.locator.x = this.X(c.length * 0.66);
1068:       positions.foreman.x = this.X(c.length - 2.4);
1069:     }
1070:     if (game.stage === 'ream') {
1071:       positions.foreman.x = this.X(c.length - 2.6);
1072:       positions.mechanic.x = this.X(-3.4);
1073:       positions.locator.x = this.X(c.length * 0.55);
1074:     }
1075:     if (game.stage === 'pull') {
1076:       positions.foreman.x = this.X(2.2);
1077:       positions.locator.x = this.X(c.length * 0.5);
1078:       positions.mud.x = this.X(v.narrow ? -9.4 : -10.3);
1079:     }
1080:     return positions;
1081:   }
