1127:   poseFor(id, game, t) {
1128:     if (id === 'locator') return game.stage === 'pilot' ? 'wand' : 'idle';
1129:     if (id === 'mud') return game.stage === 'mud' ? 'hose' : 'idle';
1130:     if (id === 'mechanic') return game.stage === 'ream' ? 'wrench' : 'idle';
1131:     if (id === 'operator') return 'console';
1132:     if (id === 'foreman') return 'tablet';
1133:     return 'idle';
1134:   }
