1103:   finishPilot() {
1104:     const c = this.contract;
1105:     const exitErr = Math.abs(this.head.d - c.exitDepth);
1106:     this.exitError = exitErr;
1107:     const routeBonus = this.prep.route === 'laser' ? 0 : this.prep.route === 'manual' ? 3 : 10;
1108:     const manualBonus = this.crew.locator.mods.manual && this.prep.route !== 'laser' ? 5 : 0;
1109:     const traj = clamp(100 - this.stats.devMax * 19 - exitErr * 13 - routeBonus + manualBonus - this.stats.rodEvents * 2, 0, 100);
1110:     const util = clamp(100 - this.stats.strikes * 48 - this.stats.fracOuts * 8, 0, 100);
1111:     this.stats.trajectoryQuality = traj;
1112:     this.stats.utilityQuality = util;
1113:     this.stats.pilotQuality = traj * 0.65 + util * 0.35;
1114:     if (exitErr > (this.prep.route === 'laser' ? 0.7 : 1.6)) {
1115:       this.extra += 1500;
1116:       this.penalties += 1500;
1117:       this.addLog('foreman', `Выход с отклонением ${fmtNum(exitErr, 1)} м. Нужна доработка котлована, штраф по смете.`, 'alert');
1118:     } else {
1119:       this.addLog('locator', `Выход в допуске: ${fmtNum(exitErr, 1)} м от проектной глубины.`, 'good');
1120:     }
1121:     this.addLog('operator', 'Пилотная скважина пройдена. Переходим к промывке.', '');
