611:   startPilot() {
612:     const p = this.prep;
613:     if (!p.scan || !p.route || !p.mud || !p.reamer) return;
614:     const cost = prepCost(p);
615:     if (state.money < cost) {
616:       toast('Недостаточно средств на подготовку объекта', 'bad');
617:       return;
618:     }
619:     state.money -= cost;
620:     this.spentPrep = cost;
621:     saveState();
622:     updateMoneyUI();
623:     this.reamer = p.reamer;
624:     this.utilities.forEach(u => { u.hit = false; });
625:     this.head = { x: 0, d: this.design[0].d, pitch: 0 };
626:     this.path = [{ x: 0, d: this.head.d }];
627:     this.pressure = 44;
628:     this.wear = 0;
629:     this.fracRisk = 0;
630:     this.stats = { ...this.stats, devMax: 0, devSum: 0, devSamples: 0, strikes: 0, fracOuts: 0, rodEvents: 0 };
631:     this.setStage('pilot');
632:     this.addLog('operator', 'Подача и вращение под контролем. Начинаем пилотную скважину.', '');
633:     this.addLog('locator', 'Сигнал есть. Веди по проекту, я корректирую глубину.', 'good');
634:     if (p.route === 'skip') this.addLog('foreman', 'Проект не нанесён — ориентируемся по локатору.', 'alert');
635:     if (p.scan === 'skip') this.addLog('locator', 'Карты нет. Буду ловить сигнал по ходу.', 'alert');
636:     sound.ok();
637:   }
