762:   updatePilotHud() {
763:     const r = this.hudRefs;
764:     if (!r.depth) return;
765:     const c = this.contract;
766:     const loc = this.crew.locator;
767:     const manualFocus = loc.mods.manual && this.prep.route !== 'laser' ? 0.82 : 1;
768:     const noise = clamp(0.42 - loc.effective * 0.05, 0.08, 0.65) * (loc.mods.noise || 1) * manualFocus;
769:     const depthRead = this.head.d + Math.sin(this.simT * 1.3) * noise + Math.sin(this.simT * 0.47 + 1.7) * noise * 0.55;
770:     const pitchRead = this.head.pitch + Math.sin(this.simT * 0.9 + 0.4) * noise * 3.2;
771:     const dev = this.head.d - designDepthAt(c, this.head.x);
772:     this.setText(r.depth, `${fmtNum(Math.max(0, depthRead), 1)} м`);
773:     this.setText(r.pitch, `${pitchRead > 0 ? '+' : ''}${Math.round(pitchRead)}°`);
774:     this.setText(r.dev, `${dev > 0 ? '+' : ''}${fmtNum(dev, 1)} м`);
775:     r.dev.parentElement.className = `hud-chip ${Math.abs(dev) > 1.05 ? 'bad' : Math.abs(dev) > 0.55 ? 'warn' : 'good'}`;
776: 
777:     const w = this.pressureWindow();
778:     const bw = this.barRefs;
779:     if (bw.aFill) {
780:       bw.aFill.style.width = `${clamp(this.pressure, 0, 100)}%`;
781:       bw.aSafe.style.left = `${w.low}%`;
782:       bw.aSafe.style.width = `${Math.max(4, w.high - w.low)}%`;
783:       this.setText(bw.aValue, `${Math.round(this.pressure)} бар`);
784:       this.setText(bw.bValue, `${Math.round(this.wear)}%`);
785:       bw.bFill.style.width = `${this.wear}%`;
786:       const prog = clamp(this.head.x / c.length * 100, 0, 100);
787:       this.setText(bw.cValue, `${Math.round(prog)}%`);
788:       bw.cFill.style.width = `${prog}%`;
789:     }
790: 
791:     const warnings = [];
792:     const ahead = this.utilities
793:       .filter(u => !u.hit && u.x > this.head.x - 1 && u.x - this.head.x < 12)
794:       .sort((a, b) => a.x - b.x)[0];
795:     if (this.input.rot && (this.input.up || this.input.down || this.holds.up || this.holds.down)) {
796:       warnings.push({ text: 'Вращение включено — идём по уклону. Для глубины выключите вращение' });
797:     }
798:     if (!this.input.rot && (this.holds.up || this.holds.down)) {
799:       warnings.push({ text: 'Точная корректировка глубины: подача замедлена' });
800:     }
801:     if (Math.abs(dev) > 0.55) warnings.push({ text: `Отклонение от проекта ${fmtNum(Math.abs(dev), 1)} м`, danger: Math.abs(dev) > 1.2 });
802:     if (this.pressure > w.high) warnings.push({ text: 'Давление выше окна — риск выхода раствора', danger: true });
803:     if (ahead) {
804:       if (ahead.revealed || ahead.detected) {
805:         warnings.push({ text: `Через ${Math.max(0, Math.round(ahead.x - this.head.x))} м — ${ahead.label}, глубина ${fmtNum(ahead.depth, 1)} м`, danger: ahead.x - this.head.x < 5 });
806:       }
807:     }
808:     if (this.wear > 72) warnings.push({ text: `Износ штанг ${Math.round(this.wear)}% — снизьте подачу`, danger: this.wear > 90 });
809:     if (this.head.d < 1.0 && this.head.x > 6) warnings.push({ text: 'Опасно малая глубина: риск выхода на поверхность', danger: true });
810:     this.setWarnings(warnings);
811:   }
