813:   updateMudHud() {
814:     const sd = this.stageData;
815:     const w = this.mudWindow();
816:     this.setText(this.hudRefs.pressure, `${Math.round(sd.pressure)} бар`);
817:     this.setText(this.hudRefs.cleaning, `${Math.round(sd.cleaning)}%`);
818:     this.setText(this.hudRefs.quality, `${Math.round(sd.quality)}%`);
819:     const bw = this.barRefs;
820:     if (bw.aFill) {
821:       bw.aFill.style.width = `${clamp(sd.pressure, 0, 100)}%`;
822:       bw.aSafe.style.left = `${w.low}%`;
