116:     const x = (c.length * i) / 20;
117:     const px = 10 + x * sx;
118:     const py = gy + designDepthAt(c, x) * sy;
119:     path += `${i ? 'L' : 'M'}${px.toFixed(1)} ${py.toFixed(1)} `;
120:   }
121:   let utils = '';
122:   c.utilities.forEach(u => {
123:     const x = 10 + u.x * sx, y = gy + u.depth * sy;
124:     utils += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="2.6" fill="${u.color}"/>`;
125:   });
126:   const band = Math.max(3, c.length * sx);
127:   return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">
128:     <defs><linearGradient id="sky${c.id}" x1="0" y1="0" x2="0" y2="1">
129:       <stop offset="0" stop-color="#0d2230"/><stop offset="1" stop-color="#3d5357"/>
130:     </linearGradient></defs>
131:     <rect width="${W}" height="${H}" fill="url(#sky${c.id})"/>
132:     <rect y="${gy}" width="${W}" height="${H - gy}" fill="#5b4a37"/>
133:     <rect y="${gy + 4}" width="${W}" height="9" fill="#6d563f"/>
134:     <rect y="${gy + 15}" width="${W}" height="13" fill="#8a7453"/>
135:     <rect y="${gy + 30}" width="${W}" height="20" fill="#4d4136"/>
136:     <path d="${path}" fill="none" stroke="#5ed6ff" stroke-width="1.4" stroke-dasharray="4 3" opacity=".85"/>
137:     <path d="${path}" fill="none" stroke="#ff7a1a" stroke-width="2.2" opacity=".9" stroke-dasharray="40 240"/>
138:     <line x1="10" y1="${gy}" x2="${10 + band}" y2="${gy}" stroke="#4a5a3a" stroke-width="2"/>
139:     ${utils}
140:     <rect x="${10 + c.length * sx - 3}" y="${gy - 5}" width="6" height="7" rx="1" fill="#ffb15c"/>
141:     <rect x="2" y="${gy - 13}" width="16" height="9" rx="1.5" fill="#d95a06"/>
142:     <rect x="5" y="${gy - 17}" width="5" height="5" rx="1" fill="#ff9a3d"/>
143:   </svg>`;
