978:       if (!u.revealed && !u.detected && Math.abs(u.x - this.head.x) < range) {
979:         u.detected = true;
980:         this.addLog('locator', `Неизвестная сеть впереди, ${Math.round(u.x - this.head.x)} м. Иду по сигналу — снизь подачу.`, 'alert');
