986:     // utility crossing
987:     for (const u of this.utilities) {
988:       if (u.hit) continue;
989:       if (prevX < u.x && this.head.x >= u.x) {
990:         if (Math.abs(this.head.d - u.depth) < u.clearance) this.strike(u);
991:       }
992:     }
993: 
994:     // deviation accounting
995:     const dev = this.head.d - designDepthAt(c, this.head.x);
996:     this.stats.devSum += Math.abs(dev) * Math.max(0.01, this.head.x - prevX);
997:     this.stats.devSamples += Math.max(0.01, this.head.x - prevX);
998:     this.stats.devMax = Math.max(this.stats.devMax, Math.abs(dev));
999: 
1000:     // pressure
1001:     const mix = MIXES[this.prep.mud] || MIXES.bentonite;
1002:     const win = this.pressureWindow();
1003:     const target = 24 + this.head.d * 3.6 + thrust * 26 + SOILS[c.soil].mud * 0.5;
1004:     this.pressure = lerp(this.pressure, target, 1 - Math.exp(-dt * 2.1));
1005:     if (this.pressure > win.high) {
1006:       const severity = (this.pressure - win.high) / 12;
1007:       this.fracRisk += dt * severity * (this.head.d < 3.2 ? 15 : 4.5);
1008:       this.stats.mudQuality = clamp(this.stats.mudQuality - dt * severity * 0.5, 0, 100);
1009:     } else {
1010:       this.fracRisk = Math.max(0, this.fracRisk - dt * 4);
1011:     }
1012:     if (this.fracRisk >= 100) this.fracOut();
1013: 
1014:     // rod wear
1015:     if (thrust > 0.72 && this.input.rot) {
1016:       const wearFactor = (op.mods.wear || 1) * (this.crew.mechanic.mods.wear || 1) * (1.18 - this.crew.mechanic.effective * 0.035);
1017:       this.wear += dt * 2.0 * wearFactor * (1 + Math.abs(dev) * 0.18);
1018:       if (this.wear >= 100) this.replaceRod();
1019:     }
1020: 
1021:     // vent cooldown
1022:     if (this.ventCd > 0) {
