766:   updatePilotHud() {
767:     const r = this.hudRefs;
768:     if (!r.depth) return;
769:     const c = this.contract;
770:     const loc = this.crew.locator;
771:     const manualFocus = loc.mods.manual && this.prep.route !== 'laser' ? 0.82 : 1;
772:     const noise = clamp(0.42 - loc.effective * 0.05, 0.08, 0.65) * (loc.mods.noise || 1) * manualFocus;
773:     const depthRead = this.head.d + Math.sin(this.simT * 1.3) * noise + Math.sin(this.simT * 0.47 + 1.7) * noise * 0.55;
774:     const pitchRead = this.head.pitch + Math.sin(this.simT * 0.9 + 0.4) * noise * 3.2;
775:     const dev = this.head.d - designDepthAt(c, this.head.x);
776:     this.setText(r.depth, `${fmtNum(Math.max(0, depthRead), 1)} м`);
777:     this.setText(r.pitch, `${pitchRead > 0 ? '+' : ''}${Math.round(pitchRead)}°`);
778:     this.setText(r.dev, `${dev > 0 ? '+' : ''}${fmtNum(dev, 1)} м`);
779:     r.dev.parentElement.className = `hud-chip ${Math.abs(dev) > 1.05 ? 'bad' : Math.abs(dev) > 0.55 ? 'warn' : 'good'}`;
780: 
781:     const w = this.pressureWindow();
782:     const bw = this.barRefs;
783:     if (bw.aFill) {
