427:   update(dt, t) {
428:     if (this.paused || this.stage === 'results') return;
429:     this.clock += dt;
430:     this.simT += dt;
431:     this.fx.scan = Math.max(0, this.fx.scan - dt);
432:     this.fx.frac = Math.max(0, this.fx.frac - dt);
433:     this.fx.shake = Math.max(0, this.fx.shake - dt * 2.2);
434:     if (this.drillPause > 0) {
435:       this.drillPause -= dt;
436:       this.updateHud();
437:       return;
438:     }
439:     switch (this.stage) {
440:       case 'pilot': this.updatePilot(dt); break;
441:       case 'mud': this.updateMud(dt); break;
442:       case 'ream': this.updateReam(dt); break;
443:       case 'pull': this.updatePull(dt); break;
444:     }
445:     this.updateHud();
446:   }
