433:     this.fx.frac = Math.max(0, this.fx.frac - dt);
434:     this.fx.shake = Math.max(0, this.fx.shake - dt * 2.2);
435:     if (this.drillPause > 0) {
436:       this.drillPause -= dt;
437:       this.updateHud();
438:       return;
439:     }
440:     switch (this.stage) {
441:       case 'pilot': this.updatePilot(dt); break;
442:       case 'mud': this.updateMud(dt); break;
443:       case 'ream': this.updateReam(dt); break;
444:       case 'pull': this.updatePull(dt); break;
445:     }
446:     this.updateHud();
