767:   updatePilotHud() {
768:     const r = this.hudRefs;
769:     if (!r.depth) return;
770:     const c = this.contract;
771:     const loc = this.crew.locator;
772:     const manualFocus = loc.mods.manual && this.prep.route !== 'laser' ? 0.82 : 1;
773:     const noise = clamp(0.42 - loc.effective * 0.05, 0.08, 0.65) * (loc.mods.noise || 1) * manualFocus;
774:     const depthRead = this.head.d + Math.sin(this.simT * 1.3) * noise + Math.sin(this.simT * 0.47 + 1.7) * noise * 0.55;
775:     const pitchRead = this.head.pitch + Math.sin(this.simT * 0.9 + 0.4) * noise * 3.2;
776:     const dev = this.head.d - designDepthAt(c, this.head.x);
777:     this.setText(r.depth, `${fmtNum(Math.max(0, depthRead), 1)} м`);
778:     this.setText(r.pitch, `${pitchRead > 0 ? '+' : ''}${Math.round(pitchRead)}°`);
779:     this.setText(r.dev, `${dev > 0 ? '+' : ''}${fmtNum(dev, 1)} м`);
780:     r.dev.parentElement.className = `hud-chip ${Math.abs(dev) > 1.05 ? 'bad' : Math.abs(dev) > 0.55 ? 'warn' : 'good'}`;
781: 
782:     const w = this.pressureWindow();
783:     const bw = this.barRefs;
784:     if (bw.aFill) {
785:       bw.aFill.style.width = `${clamp(this.pressure, 0, 100)}%`;
786:       bw.aSafe.style.left = `${w.low}%`;
787:       bw.aSafe.style.width = `${Math.max(4, w.high - w.low)}%`;
788:       this.setText(bw.aValue, `${Math.round(this.pressure)} бар`);
789:       this.setText(bw.bValue, `${Math.round(this.wear)}%`);
790:       bw.bFill.style.width = `${this.wear}%`;
791:       const prog = clamp(this.head.x / c.length * 100, 0, 100);
792:       this.setText(bw.cValue, `${Math.round(prog)}%`);
793:       bw.cFill.style.width = `${prog}%`;
794:     }
795: 
796:     const warnings = [];
797:     const ahead = this.utilities
798:       .filter(u => !u.hit && u.x > this.head.x - 1 && u.x - this.head.x < 12)
799:       .sort((a, b) => a.x - b.x)[0];
800:     if (this.input.rot && (this.input.up || this.input.down || this.holds.up || this.holds.down)) {
801:       warnings.push({ text: 'Вращение включено — идём по уклону. Для глубины выключите вращение' });
802:     }
803:     if (!this.input.rot && (this.holds.up || this.holds.down)) {
804:       warnings.push({ text: 'Точная корректировка глубины: подача замедлена' });
805:     }
806:     if (Math.abs(dev) > 0.55) warnings.push({ text: `Отклонение от проекта ${fmtNum(Math.abs(dev), 1)} м`, danger: Math.abs(dev) > 1.2 });
807:     if (this.pressure > w.high) warnings.push({ text: 'Давление выше окна — риск выхода раствора', danger: true });
808:     if (ahead) {
809:       if (ahead.revealed || ahead.detected) {
810:         warnings.push({ text: `Через ${Math.max(0, Math.round(ahead.x - this.head.x))} м — ${ahead.label}, глубина ${fmtNum(ahead.depth, 1)} м`, danger: ahead.x - this.head.x < 5 });
811:       }
812:     }
813:     if (this.wear > 72) warnings.push({ text: `Износ штанг ${Math.round(this.wear)}% — снизьте подачу`, danger: this.wear > 90 });
814:     if (this.head.d < 1.0 && this.head.x > 6) warnings.push({ text: 'Опасно малая глубина: риск выхода на поверхность', danger: true });
815:     this.setWarnings(warnings);
816:   }
