967:     this.head.d += Math.sin(rad) * speed * dt;
968:     this.head.d = clamp(this.head.d, 0.55, 9.6);
969:     if (this.head.x < 0) this.head.x = 0;
970:     if (this.head.d <= 0.56 && this.head.pitch < 0) this.head.pitch = 0;
971: 
972:     if (this.head.x - (this.path[this.path.length - 1]?.x || 0) > 0.35) {
973:       this.path.push({ x: this.head.x, d: this.head.d });
974:     }
975: 
976:     // sonde detection of unknown utilities
977:     const loc = this.crew.locator;
978:     const range = 5 + loc.effective * 2.7 * (loc.mods.detect || 1);
979:     for (const u of this.utilities) {
980:       if (!u.revealed && !u.detected && Math.abs(u.x - this.head.x) < range) {
981:         u.detected = true;
982:         this.addLog('locator', `Неизвестная сеть впереди, ${Math.round(u.x - this.head.x)} м. Иду по сигналу — снизь подачу.`, 'alert');
983:         toast('Локатор: неизвестная коммуникация на трассе', 'warn');
984:         sound.warn();
985:       }
986:     }
987: 
988:     // utility crossing
989:     for (const u of this.utilities) {
990:       if (u.hit) continue;
991:       if (prevX < u.x && this.head.x >= u.x) {
992:         if (Math.abs(this.head.d - u.depth) < u.clearance) this.strike(u);
993:       }
994:     }
995: 
996:     // deviation accounting
997:     const dev = this.head.d - designDepthAt(c, this.head.x);
998:     this.stats.devSum += Math.abs(dev) * Math.max(0.01, this.head.x - prevX);
999:     this.stats.devSamples += Math.max(0.01, this.head.x - prevX);
1000:     this.stats.devMax = Math.max(this.stats.devMax, Math.abs(dev));
1001: 
1002:     // pressure
1003:     const mix = MIXES[this.prep.mud] || MIXES.bentonite;
1004:     const win = this.pressureWindow();
1005:     const target = 24 + this.head.d * 3.6 + thrust * 26 + SOILS[c.soil].mud * 0.5;
1006:     this.pressure = lerp(this.pressure, target, 1 - Math.exp(-dt * 2.1));
1007:     if (this.pressure > win.high) {
1008:       const severity = (this.pressure - win.high) / 12;
1009:       this.fracRisk += dt * severity * (this.head.d < 3.2 ? 15 : 4.5);
1010:       this.stats.mudQuality = clamp(this.stats.mudQuality - dt * severity * 0.5, 0, 100);
1011:     } else {
1012:       this.fracRisk = Math.max(0, this.fracRisk - dt * 4);
1013:     }
1014:     if (this.fracRisk >= 100) this.fracOut();
1015: 
1016:     // rod wear
1017:     if (thrust > 0.72 && this.input.rot) {
1018:       const wearFactor = (op.mods.wear || 1) * (this.crew.mechanic.mods.wear || 1) * (1.18 - this.crew.mechanic.effective * 0.035);
1019:       this.wear += dt * 2.0 * wearFactor * (1 + Math.abs(dev) * 0.18);
1020:       if (this.wear >= 100) this.replaceRod();
1021:     }
1022: 
1023:     // vent cooldown
1024:     if (this.ventCd > 0) {
1025:       this.ventCd -= dt;
1026:       if (this.ventCd <= 0 && this.ventBtn) {
1027:         this.ventBtn.disabled = false;
1028:         this.ventBtn.textContent = 'Сбросить давление';
1029:       } else if (this.ventBtn) {
1030:         this.ventBtn.textContent = `Сброс через ${Math.ceil(this.ventCd)} с`;
1031:       }
1032:     }
1033: 
1034:     // live deck readouts
1035:     const feedVal = Math.round(thrust * 100);
1036:     this.setText($('feed-read'), `${feedVal}%`);
1037:     const mini = $('pilot-pressure-mini');
1038:     this.setText(mini, `${Math.round(this.pressure)}`);
1039:     const needle = $('pilot-needle');
1040:     if (needle) needle.style.left = `${clamp(this.pressure, 0, 100)}%`;
1041:     const band = $('pilot-band');
1042:     if (band) {
1043:       band.style.left = `${win.low}%`;
1044:       band.style.width = `${Math.max(4, win.high - win.low)}%`;
1045:     }
1046:     sound.setEngine(thrust > 0.05 ? 0.18 + thrust * 0.18 : 0.06);
1047: 
1048:     if (this.head.x >= c.length) {
1049:       this.head.x = c.length;
1050:       this.path.push({ x: c.length, d: this.head.d });
1051:       this.finishPilot();
1052:     }
1053:   }
