1202:     const target = 12 + sd.flow * 0.62 + this.contract.maxDepth * 2.3 + SOILS[this.contract.soil].mud * 0.35 + wobble + rush;
1203:     sd.pressure = lerp(sd.pressure, target, 1 - Math.exp(-dt * 1.7));
1204: 
1205:     if (sd.pressure >= w.low && sd.pressure <= w.high) {
1206:       sd.cleaning += dt * 6.1 * mix.clean;
1207:       sd.bandTime += dt;
1208:       sd.risk = Math.max(0, sd.risk - dt * 8);
1209:       sd.quality = clamp(sd.quality + dt * 0.12, 0, 100);
1210:     } else if (sd.pressure > w.high) {
1211:       const over = sd.pressure - w.high;
1212:       sd.risk += dt * over * 1.15;
1213:       sd.cleaning += dt * 0.7;
1214:       sd.quality = clamp(sd.quality - dt * (0.25 + over * 0.06), 0, 100);
1215:       if (sd.risk >= 100) this.mudFrac();
1216:     } else {
1217:       sd.cleaning += dt * 0.85;
1218:       sd.quality = clamp(sd.quality - dt * 0.08, 0, 100);
1219:       sd.risk = Math.max(0, sd.risk - dt * 2.5);
