774:     const depthRead = this.head.d + Math.sin(this.simT * 1.3) * noise + Math.sin(this.simT * 0.47 + 1.7) * noise * 0.55;
775:     const pitchRead = this.head.pitch + Math.sin(this.simT * 0.9 + 0.4) * noise * 3.2;
776:     const dev = this.head.d - designDepthAt(c, this.head.x);
777:     this.setText(r.depth, `${fmtNum(Math.max(0, depthRead), 1)} м`);
