793:       bw.cFill.style.width = `${prog}%`;
794:     }
795: 
796:     const warnings = [];
797:     const ahead = this.utilities
798:       .filter(u => !u.hit && u.x > this.head.x - 1 && u.x - this.head.x < 12)
799:       .sort((a, b) => a.x - b.x)[0];
800:     if (this.input.rot && (this.input.up || this.input.down || this.holds.up || this.holds.down)) {
801:       warnings.push({ text: 'Вращение включено — идём по уклону. Для глубины выключите вращение' });
