639:     if (p.route === 'skip') this.addLog('foreman', 'Проект не нанесён — ориентируемся по локатору.', 'alert');
640:     if (p.scan === 'skip') this.addLog('locator', 'Карты нет. Буду ловить сигнал по ходу.', 'alert');
641:     sound.ok();
