111: function miniSvg(c) {
112:   const W = 200, H = 74, gy = 24;
113:   const sx = (W - 20) / c.length;
114:   const sy = 5.2;
115:   let path = '';
116:   for (let i = 0; i <= 20; i++) {
117:     const x = (c.length * i) / 20;
118:     const px = 10 + x * sx;
119:     const py = gy + designDepthAt(c, x) * sy;
120:     path += `${i ? 'L' : 'M'}${px.toFixed(1)} ${py.toFixed(1)} `;
121:   }
122:   let utils = '';
123:   c.utilities.forEach(u => {
124:     const x = 10 + u.x * sx, y = gy + u.depth * sy;
125:     utils += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="2.6" fill="${u.color}"/>`;
126:   });
127:   const band = Math.max(3, c.length * sx);
128:   return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">
129:     <defs><linearGradient id="sky${c.id}" x1="0" y1="0" x2="0" y2="1">
130:       <stop offset="0" stop-color="#0d2230"/><stop offset="1" stop-color="#3d5357"/>
131:     </linearGradient></defs>
132:     <rect width="${W}" height="${H}" fill="url(#sky${c.id})"/>
133:     <rect y="${gy}" width="${W}" height="${H - gy}" fill="#5b4a37"/>
134:     <rect y="${gy + 4}" width="${W}" height="9" fill="#6d563f"/>
135:     <rect y="${gy + 15}" width="${W}" height="13" fill="#8a7453"/>
136:     <rect y="${gy + 30}" width="${W}" height="20" fill="#4d4136"/>
137:     <path d="${path}" fill="none" stroke="#5ed6ff" stroke-width="1.4" stroke-dasharray="4 3" opacity=".85"/>
138:     <path d="${path}" fill="none" stroke="#ff7a1a" stroke-width="2.2" opacity=".9" stroke-dasharray="40 240"/>
139:     <line x1="10" y1="${gy}" x2="${10 + band}" y2="${gy}" stroke="#4a5a3a" stroke-width="2"/>
140:     ${utils}
141:     <rect x="${10 + c.length * sx - 3}" y="${gy - 5}" width="6" height="7" rx="1" fill="#ffb15c"/>
142:     <rect x="2" y="${gy - 13}" width="16" height="9" rx="1.5" fill="#d95a06"/>
143:     <rect x="5" y="${gy - 17}" width="5" height="5" rx="1" fill="#ff9a3d"/>
144:   </svg>`;
145: }
