451:     if (this.stage === 'prep') { this.renderPrepDeck(); return; }
452:     if (this.stage === 'pilot') { this.renderPilotDeck(); return; }
453:     if (this.stage === 'mud') { this.renderMudDeck(); return; }
454:     if (this.stage === 'ream') { this.renderReamDeck(); return; }
455:     if (this.stage === 'pull') { this.renderPullDeck(); return; }
456:     deck.innerHTML = `<div class="deck-inner"><div class="prep-head"><div><p class="eyebrow">Смена завершена</p><h2>Объект передан заказчику</h2></div></div></div>`;
