459:   prepStepData() {
460:     const p = this.prep;
461:     const recipe = p.recipe ? MUD_RECIPES[p.recipe] : null;
462:     const mix = recipe ? MIXES[recipe.mix] : (p.mud ? MIXES[p.mud] : null);
463:     const swivel = SWIVELS.find(s => s.id === p.swivel);
464:     return [
465:       { id: 'scan', icon: '◎', title: 'Коммуникации', done: !!p.scan, warn: p.scan === 'skip',
466:         value: !p.scan ? 'Не проверено' : p.scan === 'georadar' ? 'Георадар · все сети' : p.scan === 'docs' ? 'Архив · неполно' : 'Пропущено · риск',
467:         act: p.scan ? 'ИЗМЕНИТЬ' : 'СКАНИРОВАТЬ' },
468:       { id: 'route', icon: '⌁', title: 'Разметка трассы', done: !!p.route, warn: p.route === 'skip',
469:         value: !p.route ? 'Проект не нанесён' : p.route === 'laser' ? 'Лазер · допуск 0,4 м' : p.route === 'manual' ? 'Ручная · допуск 1,2 м' : 'Без разметки',
470:         act: p.route ? 'ИЗМЕНИТЬ' : 'РАЗМЕТИТЬ' },
471:       { id: 'mud', icon: '◈', title: 'Буровой раствор', done: !!p.mud, warn: p.mud === 'water',
472:         value: mix ? `${mix.name} · окно +${mix.window}` : 'Не выбран',
473:         act: p.mud ? 'ИЗМЕНИТЬ' : 'ВЫБРАТЬ' },
474:       { id: 'reamer', icon: '⌀', title: 'Расширитель', done: !!p.reamer, warn: false,
475:         value: p.reamer ? `${p.reamer.dia} мм · ${p.reamer.ratio.toFixed(2)}×` : 'Не подобран',
476:         act: p.reamer ? 'ИЗМЕНИТЬ' : 'ПОДОБРАТЬ' },
477:       { id: 'safety', icon: '⛨', title: 'Ограждение зоны', done: !!p.safety, warn: false,
478:         value: p.safety ? 'Зона ограждена' : 'Не ограждена',
479:         act: p.safety ? 'СНЯТЬ' : 'ОГРАДИТЬ' }
480:     ];
481:   }
