483:   renderPrepDeck() {
484:     const steps = this.prepStepData();
485:     const ready = this.prep.scan && this.prep.route && this.prep.mud && this.prep.reamer;
486:     const missing = [
487:       !this.prep.scan && { id: 'scan', short: 'коммуникации', full: 'проверку коммуникаций' },
488:       !this.prep.route && { id: 'route', short: 'разметку', full: 'разметку трассы' },
489:       !this.prep.mud && { id: 'mud', short: 'раствор', full: 'буровой раствор' },
490:       !this.prep.reamer && { id: 'reamer', short: 'расширитель', full: 'расширитель' }
491:     ].filter(Boolean);
492:     const cost = prepCost(this.prep);
493:     $('deck').innerHTML = `<div class="deck-inner">
494:       <div class="prep-head">
495:         <div><p class="eyebrow">Этап 1 · подготовка</p><h2>Подготовка объекта</h2>
496:           <div class="sub">${this.contract.code} · ${SOILS[this.contract.soil].name} · смета подготовки ${fmtMoney(cost)}</div></div>
497:         <button class="btn btn-primary" id="btn-start-pilot">${ready ? 'Начать пилотное бурение →' : `Выбрать ${missing[0].short} →`}</button>
498:       </div>
499:       <div class="prep-steps">
500:         ${steps.map((s, i) => `<button class="prep-step ${s.done ? 'done' : ''} ${s.warn ? 'warn' : ''}" data-step="${s.id}">
501:           <span class="n">${String(i + 1).padStart(2, '0')}</span>
502:           <span class="ico">${s.icon}</span>
503:           <span class="ttl">${s.title}</span>
504:           <span class="val">${s.value}</span>
505:           <span class="act">${s.act}</span>
506:         </button>`).join('')}
507:       </div>
508:       ${ready ? '' : `<div class="prep-warn">⚠ Осталось выбрать: ${missing.map(m => m.full).join(', ')}.</div>`}
509:     </div>`;
510: 
511:     $('deck').querySelectorAll('[data-step]').forEach(btn => {
512:       btn.addEventListener('click', () => {
513:         sound.click();
514:         const id = btn.dataset.step;
515:         if (id === 'safety') {
516:           this.prep.safety = !this.prep.safety;
517:           this.addLog('foreman', this.prep.safety ? 'Зона работ ограждена, посторонние не пройдут.' : 'Ограждение снято. Риск случайного доступа вырос.', this.prep.safety ? 'good' : 'alert');
518:           this.renderPrepDeck();
519:           this.updateHud();
520:           return;
521:         }
522:         this.openPrepSheet(id);
523:       });
524:     });
525:     const start = $('btn-start-pilot');
526:     if (start) {
527:       start.addEventListener('click', () => {
528:         sound.click();
529:         if (ready) {
530:           this.startPilot();
531:         } else {
532:           toast(`Сначала выберите ${missing[0].full}`, 'warn');
533:           this.openPrepSheet(missing[0].id);
534:         }
535:       });
536:     }
537:   }
