618:   startPilot() {
619:     const p = this.prep;
620:     if (!p.scan || !p.route || !p.mud || !p.reamer) return;
621:     const cost = prepCost(p);
622:     if (state.money < cost) {
623:       toast('Недостаточно средств на подготовку объекта', 'bad');
624:       return;
625:     }
626:     state.money -= cost;
627:     this.spentPrep = cost;
628:     saveState();
629:     updateMoneyUI();
630:     this.reamer = p.reamer;
631:     this.utilities.forEach(u => { u.hit = false; });
632:     this.head = { x: 0, d: this.design[0].d, pitch: 0 };
633:     this.path = [{ x: 0, d: this.head.d }];
634:     this.pressure = 44;
635:     this.wear = 0;
636:     this.fracRisk = 0;
637:     this.stats = { ...this.stats, devMax: 0, devSum: 0, devSamples: 0, strikes: 0, fracOuts: 0, rodEvents: 0 };
638:     this.setStage('pilot');
639:     this.addLog('operator', 'Подача и вращение под контролем. Начинаем пилотную скважину.', '');
640:     this.addLog('locator', 'Сигнал есть. Веди по проекту, я корректирую глубину.', 'good');
641:     if (p.route === 'skip') this.addLog('foreman', 'Проект не нанесён — ориентируемся по локатору.', 'alert');
642:     if (p.scan === 'skip') this.addLog('locator', 'Карты нет. Буду ловить сигнал по ходу.', 'alert');
643:     sound.ok();
644:   }
