733:   pressureWindow() {
734:     const mix = MIXES[this.prep.mud] || MIXES.bentonite;
735:     const mud = this.crew.mud;
736:     const mudPenalty = this.crew.foreman.mods.mudPenalty || 0;
737:     return { low: 36, high: 64 + mix.window + mud.effective * 1.2 + (this.prep.safety ? 1 : 0) - mudPenalty * 0.5 };
