740:   mudWindow() {
741:     const mix = MIXES[this.prep.mud] || MIXES.bentonite;
742:     const mud = this.crew.mud;
743:     const mudPenalty = this.crew.foreman.mods.mudPenalty || 0;
744:     const add = this.stageData.additive ? 9 : 0;
745:     return { low: 40, high: 62 + mix.window + mud.effective * 1.3 + add - mudPenalty };
746:   }
