760:   updateHud() {
761:     this.setText($('hud-spent'), fmtMoney(this.spentPrep + this.extra));
762:     this.setText($('hud-clock'), fmtClock(this.clock));
763:     if (this.stage === 'pilot') this.updatePilotHud();
764:     else if (this.stage === 'mud') this.updateMudHud();
765:     else if (this.stage === 'ream' || this.stage === 'pull') this.updateProcessHud();
766:     else this.setWarnings([]);
