769:   updatePilotHud() {
770:     const r = this.hudRefs;
771:     if (!r.depth) return;
772:     const c = this.contract;
773:     const loc = this.crew.locator;
774:     const manualFocus = loc.mods.manual && this.prep.route !== 'laser' ? 0.82 : 1;
775:     const noise = clamp(0.42 - loc.effective * 0.05, 0.08, 0.65) * (loc.mods.noise || 1) * manualFocus;
776:     const depthRead = this.head.d + Math.sin(this.simT * 1.3) * noise + Math.sin(this.simT * 0.47 + 1.7) * noise * 0.55;
777:     const pitchRead = this.head.pitch + Math.sin(this.simT * 0.9 + 0.4) * noise * 3.2;
778:     const dev = this.head.d - designDepthAt(c, this.head.x);
779:     this.setText(r.depth, `${fmtNum(Math.max(0, depthRead), 1)} м`);
780:     this.setText(r.pitch, `${pitchRead > 0 ? '+' : ''}${Math.round(pitchRead)}°`);
781:     this.setText(r.dev, `${dev > 0 ? '+' : ''}${fmtNum(dev, 1)} м`);
782:     r.dev.parentElement.className = `hud-chip ${Math.abs(dev) > 1.05 ? 'bad' : Math.abs(dev) > 0.55 ? 'warn' : 'good'}`;
783: 
784:     const w = this.pressureWindow();
785:     const bw = this.barRefs;
786:     if (bw.aFill) {
787:       bw.aFill.style.width = `${clamp(this.pressure, 0, 100)}%`;
788:       bw.aSafe.style.left = `${w.low}%`;
789:       bw.aSafe.style.width = `${Math.max(4, w.high - w.low)}%`;
790:       this.setText(bw.aValue, `${Math.round(this.pressure)} бар`);
791:       this.setText(bw.bValue, `${Math.round(this.wear)}%`);
792:       bw.bFill.style.width = `${this.wear}%`;
793:       const prog = clamp(this.head.x / c.length * 100, 0, 100);
794:       this.setText(bw.cValue, `${Math.round(prog)}%`);
795:       bw.cFill.style.width = `${prog}%`;
796:     }
797: 
798:     const warnings = [];
799:     const ahead = this.utilities
800:       .filter(u => !u.hit && u.x > this.head.x - 1 && u.x - this.head.x < 12)
801:       .sort((a, b) => a.x - b.x)[0];
802:     if (this.input.rot && (this.input.up || this.input.down || this.holds.up || this.holds.down)) {
803:       warnings.push({ text: 'Вращение включено — идём по уклону. Для глубины выключите вращение' });
804:     }
805:     if (!this.input.rot && (this.holds.up || this.holds.down)) {
806:       warnings.push({ text: 'Точная корректировка глубины: подача замедлена' });
807:     }
808:     if (Math.abs(dev) > 0.55) warnings.push({ text: `Отклонение от проекта ${fmtNum(Math.abs(dev), 1)} м`, danger: Math.abs(dev) > 1.2 });
809:     if (this.pressure > w.high) warnings.push({ text: 'Давление выше окна — риск выхода раствора', danger: true });
810:     if (ahead) {
811:       if (ahead.revealed || ahead.detected) {
812:         warnings.push({ text: `Через ${Math.max(0, Math.round(ahead.x - this.head.x))} м — ${ahead.label}, глубина ${fmtNum(ahead.depth, 1)} м`, danger: ahead.x - this.head.x < 5 });
813:       }
814:     }
815:     if (this.wear > 72) warnings.push({ text: `Износ штанг ${Math.round(this.wear)}% — снизьте подачу`, danger: this.wear > 90 });
816:     if (this.head.d < 1.0 && this.head.x > 6) warnings.push({ text: 'Опасно малая глубина: риск выхода на поверхность', danger: true });
817:     this.setWarnings(warnings);
818:   }
