820:   updateMudHud() {
821:     const sd = this.stageData;
822:     const w = this.mudWindow();
823:     this.setText(this.hudRefs.pressure, `${Math.round(sd.pressure)} бар`);
824:     this.setText(this.hudRefs.cleaning, `${Math.round(sd.cleaning)}%`);
825:     this.setText(this.hudRefs.quality, `${Math.round(sd.quality)}%`);
