  // Maintenance is an explicit checklist; actions are completed from its deck.
}

finishJob(success, reason = '') {
  if (this.finished) return;
  this.finished = true;
  this.failed = !success;
  this.finishReason = reason || '';
  this.paused = false;
  this.input.feed = false;
