1428:   updateReam(dt) {
1429:     const sd = this.stageData;
1430:     const pulling = this.holds.feed;
1431:     sd.time += dt;
1432:     const wobble = Math.sin(this.simT * 1.4) * 2.8 + Math.sin(this.simT * 3.7 + 1) * 1.4;
1433:     const mudEmpty = this.mudStockKg <= 0;
1434:     const reamLimit = this.reamLoadLimit();
1435:     const target = this.reamBase + (pulling ? 20 : 0) - (sd.mud && !mudEmpty ? 14 : 0) + (mudEmpty ? 9 : 0) + (sd.progress / 100) * 8 + (this.reamerWear || 0) * 0.08 + wobble;
1436:     sd.load = lerp(sd.load, target, 1 - Math.exp(-dt * 3.1));
1437:     if (pulling) {
1438:       const penalty = clamp((sd.load - reamLimit) / 55, 0, 0.7);
1439:       const before = sd.progress;
